  logistics: { base: 'industrial', len: [1200, 2000], next: { highway: 2, port: 2, petro: 1, edge: 2, airport: 1 }, lamps: 'side', lampCol: 'hps', glow: 0.6, traffic: 0.8, curv: 0.6 },
