// ============================================================================
//  CPU mesh builder with per-vertex material attributes
// ============================================================================
const MAT = {
  GENERIC: 0, ROAD: 1, EMIS: 2, RETRO: 3, CONCRETE: 4, METAL: 5, TERRAIN: 6, WATER: 7, TILE: 8, SIGN: 9,
  PAINT: 10, GLASS: 11, RUBBER: 12, LIGHT: 13, PLASTIC: 14, HOOD: 15, FOLIAGE: 16, CHROME: 17, PLATE: 18, PANEL: 19, GAUGE: 20,
};
// light channels for car lamps (aMat.y when MAT.LIGHT)
const LCH = { TAIL: 1, BRAKE: 2, TURN_L: 3, TURN_R: 4, HEAD: 5, REVERSE: 6, PLATE: 7, MARKER: 8, DRL: 9, HIGHMOUNT: 10, CABIN: 11, MARKER_R: 12 };
