        for (const a of [0, 1]) m2.surf(8, 1, (b, t) => { const top = lid(a, b), bot = vadd(lid(a, 1), vscale(dn, hL)); return vlerp(top, vlerp([top[0], yH, PZ0], bot, b), t); });
        K2.black(0.6); m2.surf(4, 1, (a, t) => vlerp(vadd(lid(a, 1), vscale(dn, hL)), [lerp(xa, xb, a), yH, PZ0], t));
