  plateF: [0.335, 0.43, 0.2], rep: [1.62, 0.70], hm: [1.375, 0.12, 0.01], badge: [-0.52, 0.66, 0.07], sens: [[-0.38, 0.29], [0.38, 0.29]], rwip: [0.0, -0.42, 1.06], tow: [0.68, 0.30],
