  g.fillStyle = '#f2f8fb'; g.font = `italic 700 92px ${FONT_EN}`; g.fillText(String(Math.round(Math.max(0, G.sv))), 512, 362);
  g.fillStyle = 'rgba(160,210,230,0.75)'; g.font = `600 20px ${FONT_EN}`; g.fillText('km/h', 512, 296);
  const up = G.rv >= red - 900;   // shift hint: the gear box lights up red just before the red line
  if (up) { g.fillStyle = 'rgba(255,59,48,0.85)'; g.fillRect(670, 302, 60, 60); }
  g.fillStyle = up ? '#fff' : '#5fd8ff'; g.font = `italic 700 54px ${FONT_EN}`; g.fillText(st.gear.slice(-1), 700, 352);
  g.fillStyle = 'rgba(160,210,230,0.6)'; g.font = `500 17px ${FONT_EN}`; g.fillText(st.gear.length > 1 ? st.gear[0] : '', 700, 318);
  g.textAlign = 'left'; g.fillText(`${st.odo.toFixed(1)} km`, 300, 352);
  if (st.power != null && st.power < 0.999) { g.fillStyle = 'rgba(0,0,0,' + (1 - Math.max(0, st.power)).toFixed(3) + ')'; g.fillRect(0, 0, G.W, G.H); }
  gl.bindTexture(gl.TEXTURE_2D, G.tex);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, gl.RGBA, gl.UNSIGNED_BYTE, G.cv);
