    this.same = this.same.filter((v) => v.cop ? (v.s > ps - 1000 && v.s < ps + 1900) : (v.s > ps - 450 && v.s < ps + 1900));
    if (this.props) this.props = this.props.filter((v) => v.s > ps - 300);
