    const sirens = all.filter((c) => c.cop && c.cop.lights && c.cop.siren && c.cop.mode !== 'disabled' && c.cop.mode !== 'wait');
    // v56: every police forecast reads ONE beginning-of-frame snapshot. Sorted update order must not make the cars
