    mb.mat(MAT.GENERIC, [0.02, 0.02, 0.024], 0.35); mb.box(0, y + (C.lowBar ? 0.087 : 0.105), zc, bhw - 0.015, 0.006, C.lowBar ? 0.13 : 0.16);
