  lights.push({ p: [-0.4, T.trunk - 0.02, zr - 0.02], ch: chB, col: colB, I: 0.5, dir: -1 }); lights.push({ p: [0.4, T.trunk - 0.02, zr - 0.02], ch: chA, col: colA, I: 0.5, dir: -1 });
