    T(this.glassG.gain, 0.05 * Math.pow(vn, 3) * (0.8 + 0.4 * this.gust) * (1 - 0.3 * tube), 0.15); T(this.glassF.frequency, 800 + v * 12, 0.3);
    T(this.windG.gain, wind, 0.15); T(this.windF.frequency, 300 + v * 13 + this.gust * 120, 0.2);
