function wantedTxt(l) { return l > 0 ? '★'.repeat(l) + ' ' + LV_NAMES[l] : '未惊动警方'; }
class UI {
  constructor(game) {
    this.game = game;
    this.$ = (id) => document.getElementById(id);
    this.set = Object.assign({}, SET_DEFAULT);
    try { const s = JSON.parse(localStorage.getItem(SET_KEY) || '{}'); for (const k in SET_DEFAULT) if (k in s) this.set[k] = s[k]; } catch (e) { }
    if (MOBILE) this.set.manual = false;
    this.toastT = 0; this.quitArm = false; this.quitTm = 0;
    this.buildKeys();
    this.buildSettings();
    this.$('bResume').onclick = () => game.resume();
    this.$('bQuit').onclick = () => this.quitClick();
    this.$('bPauseSet').onclick = () => this.openSettings(true);
    this.$('bBack').onclick = () => this.openSettings(false);
    this.$('bReset').onclick = () => this.resetSettings();
  }
  // the upload page (see Lot.renderUpload) is the end screen now
  showEnd(st, res) { this.$('endScr').classList.add('show'); this.game.lot.renderUpload(st, res); }
  hideEnd() { this.$('endScr').classList.remove('show'); const w = this.$('upWrap'); if (w) w.innerHTML = ''; }
  save() { try { localStorage.setItem(SET_KEY, JSON.stringify(this.set)); } catch (e) { } }
  buildKeys() {
    const h = KEYS_HELP.map(([k, d]) => `<div class="k"><b>${k}</b><span>${d}</span></div>`).join('');
    for (const id of ['keys1', 'keys2']) { const el = this.$(id); if (el) el.innerHTML = h; }
  }
  // the pause menu list ('run') and the parked-car settings page ('lot') are built from the same schema
  buildSettings() { this.buildList(this.$('setList'), 'run'); this.buildList(this.$('setListLot'), 'lot'); }
  buildList(root, scope) {
    if (!root) return;
    root.innerHTML = '';
    for (const it of SETTINGS_SCHEMA) {
      if (it.w && it.w !== scope) continue;
      if (MOBILE ? (it.dbg || it.desk) : it.mob) continue;
      if (it.g) { const h = document.createElement('div'); h.className = 'sg'; h.textContent = it.g; root.appendChild(h); continue; }
      const row = document.createElement('div'); row.className = 'sr';
      const lab = document.createElement('label'); lab.textContent = it.n; row.appendChild(lab);
      const val = this.set[it.k];
      if (it.t === 'btn') {
        const box = document.createElement('div'); box.className = 'seg';
        for (const [code, name] of it.o) { const b = document.createElement('button'); b.textContent = name; b.onclick = () => { if (this.game.act) this.game.act(code); }; box.appendChild(b); }
        row.appendChild(box);
      } else if (it.t === 'sel') {
        const box = document.createElement('div'); box.className = 'seg';
        for (const [v, name] of it.o) {
          const b = document.createElement('button'); b.textContent = name;
          if (String(v) === String(val)) b.className = 'on';
          b.onclick = () => { this.set[it.k] = v; this.save(); for (const c of box.children) c.className = ''; b.className = 'on'; this.game.applySettings(it.k); };
          box.appendChild(b);
        }
        row.appendChild(box);
      } else if (it.t === 'tog') {
        const b = document.createElement('button'); b.className = 'tog' + (val ? ' on' : ''); b.textContent = val ? '开' : '关';
        b.onclick = () => { this.set[it.k] = !this.set[it.k]; this.save(); b.className = 'tog' + (this.set[it.k] ? ' on' : ''); b.textContent = this.set[it.k] ? '开' : '关'; this.game.applySettings(it.k); };
        row.appendChild(b);
      } else {
        const r = document.createElement('input'); r.type = 'range'; r.min = it.a; r.max = it.b; r.step = 0.05; r.value = val;
        const out = document.createElement('span'); out.className = 'rv'; out.textContent = Math.round(val * 100) + '%';
        const fill = () => r.style.setProperty('--p', (100 * (parseFloat(r.value) - it.a) / (it.b - it.a)) + '%');
        fill();
        r.oninput = () => { fill(); this.set[it.k] = parseFloat(r.value); out.textContent = Math.round(this.set[it.k] * 100) + '%'; this.save(); this.game.applySettings(it.k); };
        row.appendChild(r); row.appendChild(out);
      }
      root.appendChild(row);
    }
  }
  refreshSettings() { this.buildSettings(); }
  // "restore defaults" keeps what the garage decides (engine / gearbox / paint / turbo) and edits the shared settings object in place
  resetSettings() {
    const keep = { engine: this.set.engine, gearbox: this.set.gearbox, paint: this.set.paint, turbo: this.set.turbo };
    const d = Object.assign({}, SET_DEFAULT, keep);
    for (const k in d) this.set[k] = d[k];
    this.save(); this.buildSettings(); this.game.applySettings();
  }
  // "end stream": asks twice (a mis-click must not throw a run away)
  quitClick() {
    const b = this.$('bQuit'); if (!b) return;
    if (!this.quitArm) {
      this.quitArm = true; b.classList.add('warn');
      const P = this.game.police;
      b.textContent = P && P.state === 'pursuit' ? '确认结束？将按被捕结算' : '确认结束直播？';
      clearTimeout(this.quitTm); this.quitTm = setTimeout(() => this.disarmQuit(), 3500);
      return;
    }
    this.disarmQuit();
    this.game.quitRun();
  }
  disarmQuit() {
    this.quitArm = false; clearTimeout(this.quitTm);
    const b = this.$('bQuit'); if (b) { b.classList.remove('warn'); b.textContent = '结束直播'; }
  }
  showPause(on) {
    this.$('pause').classList.toggle('show', on);
    this.disarmQuit();
    if (on) { this.buildSettings(); this.openSettings(false); }
  }
  openSettings(on) {
    this.$('pauseMain').style.display = on ? 'none' : '';
    this.$('settings').style.display = on ? '' : 'none';
  }
  toast(msg) {
    const el = this.$('toast'); el.textContent = msg; el.classList.add('show'); this.toastT = 1.8;
  }
  update(dt, g) {
    if (this.toastT > 0) { this.toastT -= dt; if (this.toastT <= 0) this.$('toast').classList.remove('show'); }
    const hud = this.$('hud');
    const show = !MOBILE && this.set.hud && g.mode === 'play';
    hud.style.display = show ? '' : 'none';
    if (!show) return;
    this.hudT = (this.hudT || 0) - dt; if (this.hudT > 0) return; this.hudT = 0.08;
    const P = g.player, e = P.eng;
    const gearTxt = P.reverse ? 'R' : (P.manual ? 'M' : 'D') + P.gear;
    const rpmF = sat(P.rpm / (e.red + 400));
    const redF = e.red / (e.red + 400);
    const bars = 24, on = Math.round(rpmF * bars);
    let bar = '';
    for (let i = 0; i < bars; i++) bar += `<i class="${i < on ? (i / bars > redF ? 'r' : 'o') : ''}"></i>`;
    const kmh = Math.round(Math.abs(P.v) * 3.6);
    hud.innerHTML = `<div class="hg"><span class="gear">${gearTxt}</span><span class="spd">${kmh}<small>km/h</small></span></div>
<div class="bar">${bar}</div><div class="rpm">${Math.round(P.rpm / 50) * 50} rpm${P.boost > 0.05 ? ` · 增压 ${(P.boost * 1.1).toFixed(1)} bar` : ''}</div>
<div class="st">${P.manual ? '手动挡' : '自动挡'}${P.gearbox === 'sequential' ? ' · 序列式' : P.gearbox === 'dct' ? ' · 双离合' : ''}${P.hyb ? ` · 电机 ${Math.floor(P.hyb.E)} 档` : ''}${P.shiftT > 0 ? ` · 换挡 ${P.shiftFrom} → ${P.shiftTarget}` : ''} · 雨刮 ${WIPER_NAMES[g.wipers.mode]} · ${g.highBeam ? '远光' : '近光'}${P.autopilot ? ' · <b>自动驾驶</b>' : ''}</div>
<div class="st">${WEATHER_NAMES[g.weather.state] || ''}${g.set.weather === 'auto' ? '（自动）' : ''} · ${ZONE_NAMES[g.zoneType] || ''} · 里程 ${(P.odo / 1000).toFixed(1)} km</div>
<div class="st">车况 <b style="color:${P.hp > 60 ? '#8f8' : P.hp > 30 ? '#fc6' : '#f66'}">${P.wrecked?'撞毁':P.hp<=0?'严重受损':Math.max(0,Math.round(P.hp))+'%'}</b>${P.god ? ' · 无敌' : ''}</div>
<div class="st" style="opacity:.6">建筑压路检测 ${BLDSTAT.seen} 栋 · 已回收 ${BLDSTAT.fixed}</div>`;
  }
}
const ZONE_NAMES = { city: '城市高架', suburb: '城郊快速路', country: '山野高速', industrial: '工业区', bridge: '跨江大桥', tunnel: '隧道',
  highway: '城外高速', power: '高压电网走廊', airport: '机场', petro: '石化园区', port: '港区', seabridge: '跨海大桥', farm: '田园乡村', coast: '滨海公路', link: '互通匝道', edge: '城郊结合部', logistics: '物流园区' };
function fmtTime(t) { t = Math.round(t); const h = Math.floor(t / 3600), m = Math.floor(t / 60) % 60, s = t % 60; return (h ? h + ':' : '') + String(m).padStart(h ? 2 : 1, '0') + ':' + String(s).padStart(2, '0'); }

// ---- 12b_profile.js ----
// ============================================================================
//  Creator profile: garage catalogue, economy constants, save file (localStorage)
//  All prices are US dollars. Everything about the money loop is tweakable in ECON / CARS below.
// ============================================================================
const SAVE_KEY = 'dashcam.save.v1';
const fmtMoney = (n) => (n < 0 ? '-$' : '$') + Math.abs(Math.round(n || 0)).toLocaleString('en-US');
const fmtNum = (n) => Math.round(n || 0).toLocaleString('en-US');
function fmtFans(n) { n = Math.round(n || 0); return n >= 10000 ? (n / 10000).toFixed(n >= 100000 ? 0 : 1) + ' 万' : String(n); }
function escHtml(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }

// ---------------------------------------------------------------- the garage
// body: shape used for the garage render (the in-car cabin is shared by every car); eng: key of ENGINES;
// mass / cda / pwr (torque scale) / fd (final-drive scale): physics tune; value: base price used for repair bills.
const CARS = [
  { id: 'wren', name: 'WREN 2.0', cn: '鹪鹩', cls: 'C', body: 'hatch', eng: 'i4', layout: 'I4', engTxt: '2.0L 自然吸气直四', price: 0, value: 9000,
    mass: 1300, cda: 0.60, pwr: 0.78, fd: 1.07, turboOk: false, turboPrice: 0, seqPrice: 9500, paintK: 1,
    blurb: '两厢掀背车，2.0L 自然吸气直列四缸，六速变速箱，整备质量 1300 kg。轴距短，转向响应直接；零部件通用，维修成本低。' },
  { id: 'nightjar', name: 'NIGHTJAR 3.0', cn: '夜鹰', cls: 'B', body: 'sedan2', eng: 'i6', layout: 'I6', engTxt: '3.0L 自然吸气直六', price: 62000, value: 62000,
    mass: 1650, cda: 0.62, pwr: 1.0, fd: 1.0, turboOk: false, turboPrice: 0, seqPrice: 18000, paintK: 2.5,
    blurb: '中型运动轿车，3.0L 自然吸气直列六缸，峰值扭矩 365 N·m（1900–4800 rpm）。整备质量 1650 kg，长轴距，高速稳定性好。' },
  { id: 'xr7', name: 'XR-7 1.3R', cn: '游隼', cls: 'B', body: 'sport', eng: 'r2', layout: 'R2', engTxt: '1.3L 双涡轮双转子', stockTurbo: true, price: 88000, value: 88000,
    mass: 1280, cda: 0.56, gripL: 1.14, pwr: 1.0, fd: 1.0, turboOk: false, turboPrice: 0, seqPrice: 21000, paintK: 3,
    blurb: '双门轿跑，前中置 1.3L 双转子发动机，原厂顺序式双涡轮增压（0.8 bar），红线 8500 rpm，整备质量 1280 kg，前后配重接近 50:50。弹出式卤素大灯。' },
  { id: 'harpy', name: 'HARPY 5.0', cn: '角雕', cls: 'A', body: 'muscle', eng: 'v8', layout: 'V8', engTxt: '5.0L 自然吸气 V8', price: 145000, value: 145000,
    mass: 1780, cda: 0.66, pwr: 1.0, fd: 1.0, turboOk: true, turboPrice: 42000, seqPrice: 28000, paintK: 4,
    blurb: '宽体双门跑车，5.0L 自然吸气 V8，峰值扭矩 430 N·m @ 4500 rpm，整备质量 1780 kg。可选装涡轮增压套件，车身维修成本高。' },
  // v81: experimental hybrid GT. The race version was built for a series that was stopped over safety; the maker had to
  // homologate a road version first and now sells it to recover the cost. cls '？': it never left the test stage.
  { id: 'xh6', name: 'XH-6 3.0H', cn: '', cls: '？', body: 'gt', eng: 'i6h', layout: 'I6 + E', engTxt: '3.0L 双涡轮直六 + 电机', stockTurbo: true, hybrid: true, noUp: true, dct: true,
    price: 380000, value: 380000, mass: 1540, cda: 0.70, gripL: 1.2, brkMul: 1.45, brkGrip: 1.12, df: 0.34, steerMul: 1.16, pwr: 1.0, fd: 1.0, turboOk: false, turboPrice: 0, seqPrice: 0, paintK: 6,
    motorKw: 330, t100: 2.9,
    blurb: '实验性混动 GT，为一项因安全问题停办的赛事而生，停办后只剩量产版在售。前中置 3.0L 双涡轮直六 + 前轴电机，8 速双离合，大尾翼带来高下压力。' },
];
function carById(id) { for (const c of CARS) if (c.id === id) return c; return CARS[0]; }
const PAINT_PRICE = { black: 0, white: 0, red: 900, blue: 900, grey: 1300, green: 1300 };
function paintPrice(car, key) { return Math.round((PAINT_PRICE[key] || 0) * car.paintK / 100) * 100; }

// peak power / torque / top speed from the same tables the physics uses
function carSpec(car, turbo) {
  const e = ENGINES[car.eng], tk = car.hybrid ? 1 : turbo || car.stockTurbo ? 1.35 : 1;   // the hybrid's table is already its full-boost curve
  let pk = 0, tq = 0;
  for (let r = 1000; r <= e.red + 200; r += 100) {
    const t = lerpCurve(e.torque, r) * car.pwr * tk, kw = t * r / 9549;
    if (kw > pk) pk = kw;
    if (t > tq) tq = t;
  }
  const gTop = e.gears[e.gears.length - 1], fd = e.fd * car.fd;
  let top = 0;
  for (let v = 20; v < 110; v += 0.5) {
    const rpm = v / 0.335 * gTop * fd * 60 / TAU;
    if (rpm > e.limiter) break;
    const Fw = lerpCurve(e.torque, rpm) * car.pwr * tk * gTop * fd * 0.9 / 0.335;
    const Fr = 0.5 * 1.2 * car.cda * v * v + 0.012 * car.mass * 9.81;
    if (Fw < Fr) break;
    top = v;
  }
  if (car.motorKw) pk += car.motorKw * 0.85;   // system output: engine + the motor's share at that speed
  return { kw: pk, hp: pk * 1.341, nm: tq, top: top * 3.6, mass: car.mass, t100: car.t100 };
}
// engine layout badge (I4 / I6 / V8): plain lettering, no pictograms
function engTag(layout) { return '<span class="engTag">' + escHtml(layout) + '</span>'; }

// ---------------------------------------------------------------- economy knobs
const ECON = {
  k: 9,                                   // $ per "hype second"
  base: 4.5,                              // $ per second while rolling faster than 30 km/h (steady trickle of viewers)
  // v81: steady 100-150 km/h driving is worth watching too (it used to earn almost nothing below 110)
  speed: [[50, 0], [80, 0.25], [120, 0.6], [160, 1.0], [200, 1.4], [260, 2.4], [300, 3.2]],   // km/h -> hype
  aud: 0.3,                               // v81: a bigger room tips more: x(0.7 + aud * sqrt(viewers / 100))
  wanted: [1.0, 1.2, 1.5, 1.8, 2.2, 2.7], // multiplier by wanted level (index = stars)
  copHype: 0.25, heliHype: 0.35, copMax: 5, copRange: 140,            // chase hype: per cop within copRange metres, helicopter on station
  zone: { tunnel: 0.35, bridge: 0.30, seabridge: 0.35, city: 0.25, port: 0.15, airport: 0.15, petro: 0.15, industrial: 0.12, power: 0.10, coast: 0.10 },
  wx: { rain: 0.12, fog: 0.18, snow: 0.22, thunder: 0.25 },
  envDecay: 150,                          // s: the same place + weather gets boring
  fatigueSpeed: 150, fatigueT: 300, fatigueMin: 0.5,   // flat out for too long gets boring, too
  ev: { nearMiss: 90, copsDown: 450, escapes: 1200, scrape: 40, crash: 120, smash: 300, chain: 500, copFront: 150 }, evDecay: 0.85, evFloor: 0.15,
  civ: { crash: 4, smash: 10, chainN: 3, chainT: 8 },   // v80: civilian collisions by severity; 3+ different cars within 8 s = pile-up
  copFront: { t: 12, dd: 2.2, s0: 5, s1: 70, kmh: 60 }, // v80: a pursuing cop held directly ahead for 12 s
  lvBonus: [0, 250, 700, 1500, 3200, 6500],            // one-off tip for each new star
  fine: [0, 800, 1600, 3800, 7500, 13000],             // fine when caught, by stars
  // v80 wreck bill: value x (base + worn frame + crash violence) + labour; a light write-off of a fresh car costs far less than
  // a 250 km/h pile-up of a car that was already battered
  repair: { base: 0.025, frame: 0.035, crash: 0.05, sev0: 15, sev1: 40, labour: 350 }, repairMin: 800,
  // v81: bills grow slower than the price (parts for a dear car are dear, but not in proportion), and viewers tip more for a
  // car worth watching: x(1 + 0.22 ln(value / 9000)) -> NIGHTJAR ~1.4, XR-7 ~1.5, HARPY ~1.6, XH-6 ~1.8
  repairExp: 0.8, repairRef: 9000, carTip: 0.22,
  div: { per: 0.06, cap: 0.42, zoneMin: 20, wxMin: 30 },
};

// ---------------------------------------------------------------- save file
class Profile {
  constructor() { this.data = this.defaults(); this.load(); }
  defaults() {
    return {
      v: 1, money: 0, fans: 0, name: '夜行记录仪', cur: 'wren',
      cars: { wren: { own: true, paint: 'black', paints: [], seq: false, turbo: false } },
      tot: { runs: 0, tips: 0, fines: 0, repair: 0, km: 0, time: 0, arrests: 0, wrecks: 0, quits: 0, top: 0, maxLevel: 0, peak: 0 },
      last: [], flags: { ignSeen: false },
    };
  }
  // anything read from disk or imported by hand goes through here
  sanitize(raw) {
    const d = this.defaults();
    if (!raw || typeof raw !== 'object') return d;
    const num = (x, def) => (typeof x === 'number' && isFinite(x) && x >= 0 ? x : def);
    const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
    d.money = num(raw.money, 0); d.fans = num(raw.fans, 0);
    if (typeof raw.name === 'string' && raw.name.length > 0 && raw.name.length < 24) d.name = raw.name;
    if (raw.tot && typeof raw.tot === 'object') for (const k in d.tot) d.tot[k] = num(raw.tot[k], 0);
    if (raw.cars && typeof raw.cars === 'object') {
      for (const c of CARS) {
        if (!has(raw.cars, c.id)) continue;
        const r = raw.cars[c.id];
        if (!r || typeof r !== 'object' || !r.own) continue;
        const paints = Array.isArray(r.paints) ? r.paints.filter((p) => PAINT_OPTS.some((o) => o[0] === p)) : [];
        const valid = (p) => PAINT_OPTS.some((o) => o[0] === p) && (paintPrice(c, p) === 0 || paints.includes(p));
        d.cars[c.id] = { own: true, paint: valid(r.paint) ? r.paint : 'black', paints, seq: !!r.seq, turbo: !!(r.turbo && c.turboOk) };
      }
    }
    if (typeof raw.cur === 'string' && has(d.cars, raw.cur)) d.cur = raw.cur;
    if (Array.isArray(raw.last)) {
      for (const l of raw.last.slice(0, 4)) {
        if (!l || typeof l !== 'object') continue;
        d.last.push({
          t: num(l.t, 0), title: String(l.title || '').slice(0, 80), tips: num(l.tips, 0), net: typeof l.net === 'number' && isFinite(l.net) ? l.net : 0,
          kind: ['arrest', 'wreck', 'quit'].includes(l.kind) ? l.kind : 'quit', car: String(l.car || '').slice(0, 24), lv: Math.min(5, num(l.lv, 0)), top: num(l.top, 0),
          thumb: typeof l.thumb === 'string' && l.thumb.indexOf('data:image/') === 0 && l.thumb.length < 120000 ? l.thumb : '',
        });
      }
    }
    if (raw.flags && typeof raw.flags === 'object') d.flags.ignSeen = !!raw.flags.ignSeen;
    return d;
  }
  load() {
    let raw = null;
    try { raw = JSON.parse(localStorage.getItem(SAVE_KEY) || 'null'); } catch (e) { raw = null; }
    this.data = this.sanitize(raw);
    window.__dashcamKm = this.data.tot.km;
  }
  save() {
    try { localStorage.setItem(SAVE_KEY, JSON.stringify(this.data)); return true; }
    catch (e) {
      try { const d = JSON.parse(JSON.stringify(this.data)); for (const l of d.last) l.thumb = ''; localStorage.setItem(SAVE_KEY, JSON.stringify(d)); return true; } catch (e2) { return false; }
    }
  }
  exportText() { return JSON.stringify(this.data); }
  importText(text) {
    let raw = null;
    try { raw = JSON.parse(text); } catch (e) { return false; }
    if (!raw || typeof raw !== 'object' || typeof raw.money !== 'number' || !raw.cars || typeof raw.cars !== 'object') return false;
    this.data = this.sanitize(raw); this.save(); return true;
  }
  reset() { this.data = this.defaults(); this.save(); window.__dashcamKm = 0; }
  car() { return carById(this.data.cur); }
  has(id) { return Object.prototype.hasOwnProperty.call(this.data.cars, id); }
  st(id) { return this.has(id) ? this.data.cars[id] : null; }
  paintOwned(id, key) { const c = carById(id), s = this.st(id); return !!(s && (paintPrice(c, key) === 0 || s.paints.includes(key))); }
  // what the car is worth (repair bills): base value + installed upgrades
  valueOf(id) { const c = carById(id), s = this.st(id); if (!s) return 0; return c.value + (s.seq ? c.seqPrice : 0) + (s.turbo ? c.turboPrice : 0); }
  buyCar(id) {
    const c = carById(id);
    if (this.has(id)) return { ok: false, msg: '这台车已经在车库里了' };
    if (this.data.money < c.price) return { ok: false, msg: '余额不足' };
    this.data.money -= c.price;
    this.data.cars[id] = { own: true, paint: 'black', paints: [], seq: false, turbo: false };
    this.data.cur = id; this.save();
    return { ok: true, msg: '已购入 ' + c.name + '，并设为座驾' };
  }
  setCur(id) { if (!this.has(id)) return { ok: false, msg: '还没有这台车' }; this.data.cur = id; this.save(); return { ok: true, msg: '已设为座驾：' + carById(id).name }; }
  usePaint(id, key) { const s = this.st(id); if (!s || !this.paintOwned(id, key)) return { ok: false, msg: '还没有这个颜色' }; s.paint = key; this.save(); return { ok: true, msg: '已换上新车漆' }; }
  buyPaint(id, key) {
    const c = carById(id), s = this.st(id), pr = paintPrice(c, key);
    if (!s) return { ok: false, msg: '先购入这台车' };
    if (this.paintOwned(id, key)) return this.usePaint(id, key);
    if (this.data.money < pr) return { ok: false, msg: '余额不足' };
    this.data.money -= pr; s.paints.push(key); s.paint = key; this.save();
    return { ok: true, msg: '已喷涂新车漆' };
  }
  buyUp(id, kind) {
    const c = carById(id), s = this.st(id);
    if (!s) return { ok: false, msg: '先购入这台车' };
    if (c.noUp) return { ok: false, msg: '原厂已配备，不能改装' };
    if (kind === 'turbo' && !c.turboOk) return { ok: false, msg: '这台车没有涡轮套件' };
    if (s[kind]) return { ok: false, msg: '已经装好了' };
    const pr = kind === 'seq' ? c.seqPrice : c.turboPrice;
    if (this.data.money < pr) return { ok: false, msg: '余额不足' };
    this.data.money -= pr; s[kind] = true; this.save();
    return { ok: true, msg: kind === 'seq' ? '序列式变速箱已装好' : '涡轮套件已装好' };
  }
  addMoney(n) { this.data.money += n; this.save(); }
  markIgnSeen() { if (!this.data.flags.ignSeen) { this.data.flags.ignSeen = true; this.save(); } }
  // end of a stream: res comes from Stream.finish()
  applyRun(res) {
    const d = this.data, t = d.tot;
    d.money = res.balance; d.fans += res.fansGain;
    t.runs++; t.tips += res.tips; t.km += res.dist / 1000; t.time += res.time;
    if (res.kind === 'arrest') { t.arrests++; t.fines += res.deduct; } else if (res.kind === 'wreck') { t.wrecks++; t.repair += res.deduct; } else t.quits++;
    t.top = Math.max(t.top, res.top); t.maxLevel = Math.max(t.maxLevel, res.maxLevel); t.peak = Math.max(t.peak, res.peak);
    d.last.unshift({ t: Date.now(), title: res.title, tips: res.tips, net: res.net, kind: res.kind, car: res.car, lv: res.maxLevel, top: res.top, thumb: res.cover || '' });
    if (d.last.length > 4) d.last.length = 4;
    this.save();
    window.__dashcamKm = t.km;
    if (window.ToyRank && window.ToyRank.report) window.ToyRank.report(t.km);
  }
}

// ---- 12c0_comments.js ----
// ============================================================================
//  Chat / comment voices for the upload page. Silent during the drive: Stream.say() queues short lines with a stream
//  timestamp, Stream.finish() turns them into threads (nicknames, IP region, likes, replies, answers from the author).
//  Everything is written the way people actually type under a night-drive stream: fragments, memes, no polish.
// ============================================================================

// ---------------------------------------------------------------- lines by moment ({n}: speed or stars, {cn}: car nickname)
