const CM_REGULARS = ['老陈夜班', 'turbo_lag', '凌晨三点的猫', '小满', '阿K修车'];
const CM_EMOJI = { doge: '🐶', 笑哭: '😂', 吃瓜: '🍉', 呆: '😳', 思考: '🤔', OK: '👌', 惊讶: '😲', 捂脸: '🤦', 妙啊: '👏', 哭: '😭', 偷笑: '🤭', 疑惑: '❓', 墨镜: '😎', 无语: '😑', 滑稽: '🤪', 加油: '💪', 吓: '😱', 火: '🔥' };
const cmEmoji = (s) => String(s).replace(/\[([^\]\s]{1,4})\]/g, (m, k) => CM_EMOJI[k] || m);
const cmPick = (a) => a[Math.floor(Math.random() * a.length)];
const cmFill = (s, c) => s.replace(/\{(\w+)\}/g, (m, k) => (c && c[k] != null ? c[k] : ''));
function cmNick(used) {
  let n = '';
  for (let k = 0; k < 8; k++) {
    const r = Math.random();
    if (r < 0.1) n = '用户' + (1000000000 + Math.floor(Math.random() * 8999999999));
    else if (r < 0.15) n = '回声用户_' + Math.floor(100000 + Math.random() * 899999);
    else {
      n = cmPick(CM_NICKS);
      const q = Math.random();
      if (q < 0.3) n += /^[\x00-\x7f]+$/.test(n) ? cmPick(['_', '', '']) + Math.floor(Math.random() * 100) : cmPick(['', '', '666', '1998', '2000', '1024', '_', '丶']) + (Math.random() < 0.3 ? Math.floor(Math.random() * 100) : '');
    }
    if (!used || !used.has(n)) break;
  }
  if (used) used.add(n);
  return n;
}
// the way people laugh and swear is never the same length twice
function cmJitter(s) {
  if (Math.random() < 0.18) s = s.replace(/哈{3,}/, '哈'.repeat(3 + Math.floor(Math.random() * 7)));
  if (Math.random() < 0.12) s = s.replace('卧槽', cmPick(['握草', '我草', '我超', '卧槽']));
  if (Math.random() < 0.1 && /[！!]$/.test(s)) s += cmPick(['！', '！！']);
  if (Math.random() < 0.08 && /^[笑草牛6]/.test(s) && s.length < 4) s += s.charAt(s.length - 1).repeat(1 + Math.floor(Math.random() * 3));
  return s;
}
// "3分钟前" style age for a comment posted `sec` before the page opened
function cmAgo(sec) {
  sec = Math.max(0, sec);
  if (sec < 60) return '刚刚';
  if (sec < 3600) return Math.floor(sec / 60) + '分钟前';
  return Math.floor(sec / 3600) + '小时前';
}
const fmtW = (n) => { n = Math.round(n || 0); return n >= 10000 ? (n / 10000).toFixed(n >= 100000 ? 0 : 1) + '万' : fmtNum(n); };

