// ---- 12c_stream.js ----
// ============================================================================
//  Live stream scoring: hype -> viewers -> tips, forum replies, highlight shots.
//  Runs silently during the drive (nothing is shown in-game); the upload page reveals it afterwards.
// ============================================================================
function hypeSpeed(kmh) {
  const T = ECON.speed;
  if (kmh <= T[0][0]) return 0;
  for (let i = 1; i < T.length; i++) if (kmh <= T[i][0]) return lerp(T[i - 1][1], T[i][1], (kmh - T[i - 1][0]) / (T[i][0] - T[i - 1][0]));
  return T[T.length - 1][1];
}

class Stream {
  constructor(game) { this.g = game; this.begin(); }
  begin() {
    this.t = 0;
    this.acc = { base: 0, speed: 0, chase: 0, env: 0 };
    this.evAcc = {}; this.evN = {};
    for (const k of ['nearMiss', 'copsDown', 'escapes', 'scrape', 'crash', 'smash', 'chain', 'copFront']) { this.evAcc[k] = 0; this.evN[k] = 0; }
    this.civ = []; this.chainL = []; this.cfT = 0; this.cfGap = 0;
    this.seen = { nearMiss: 0, copsDown: 0, escapes: 0, hits: 0 };
    this.lvBonus = 0; this.lastLv = 0; this.maxLv = 0;
    { const pf = this.g && this.g.profile, c = pf && pf.car(); const v = c ? pf.valueOf(c.id) : 9000; this.carMul = 1 + ECON.carTip * Math.log(Math.max(1, v / ECON.repairRef)); }
    this.fat = 0; this.envT = {}; this.zoneT = {}; this.wxT = {};
    this.lastZone = ''; this.lastWx = 'clear'; this.m200 = false; this.m250 = false; this.heliSeen = false; this.droveShot = false;
    this.hype = 0; this.hs = 0;
    this.fans = this.g.profile ? this.g.profile.data.fans : 0;
    this.viewers = 20 + Math.sqrt(this.fans) * 1.2; this.peak = this.viewers; this.views = 0;
    this.curve = []; this.curveDt = 2; this.curveT = 0; this.marks = [];
    this.cm = []; this.cmT = {}; this.cmNext = 18 + Math.random() * 10; this.pend = []; this.said = new Set(); this.used = new Set(); this.ppl = {};
    this.kmh = 0; this.regN = {};
    this.regs = CM_REGULARS.slice().sort(() => Math.random() - 0.5).slice(0, 2);
    this.snaps = []; this.shotT = -99; this.topKmh = 0; this.maxCops = 0;
    this.say('start');
  }
  // ---------------------------------------------------------------- per frame (only while driving, never during the ignition sequence)
  tick(dt, g) {
    const P = g.player, pol = g.police, S = g.stats, E = ECON;
    const kmh = Math.abs(P.v) * 3.6;
    this.t += dt; this.kmh = kmh;
    if (kmh > this.topKmh) this.topKmh = kmh;
    // police presence
    const lv = pol && pol.state === 'pursuit' ? Math.max(1, pol.level | 0) : 0;
    let near = 0;
    if (lv > 0 && pol.units) {
      for (const u of pol.units) {
        const c = u.cop; if (!c) continue;
        const m = c.mode; if (m === 'disabled' || m === 'giveup' || m === 'withdraw' || m === 'lead') continue;
        if (Math.abs(u.s - P.s) < E.copRange) near++;
      }
    }
    const heli = lv > 0 && !!pol.heli && !pol.heli.leave;
    if (near > this.maxCops) this.maxCops = near;
    // hype
    this.fat = kmh > E.fatigueSpeed ? Math.min(E.fatigueT, this.fat + dt) : Math.max(0, this.fat - dt * 0.5);
    const fk = 1 - (1 - E.fatigueMin) * this.fat / E.fatigueT;
    const hs = hypeSpeed(kmh) * fk;
    const hc = lv > 0 ? E.copHype * Math.min(E.copMax, near) + (heli ? E.heliHype : 0) : 0;
    const he = this.envHype(g, dt);
    const wm = E.wanted[Math.min(5, lv)] * (this.carMul || 1);
    const au = (1 - E.aud) + E.aud * Math.sqrt(Math.max(25, this.viewers) / 100), wk = wm * E.k * au * dt;
    this.acc.speed += hs * wk; this.acc.chase += hc * wk; this.acc.env += he * wk;
    if (kmh > 30) this.acc.base += E.base * (this.carMul || 1) * au * dt;
    this.hype = (hs + hc + he) * wm;
    // one-off events
    for (const key of ['nearMiss', 'copsDown', 'escapes']) {
      const cur = S[key] | 0;
      for (let i = this.seen[key]; i < cur; i++) this.event(key, kmh, wm);
      this.seen[key] = cur;
    }
    this.civTick(g, kmh, wm, lv);
    if ((S.hits | 0) > this.seen.hits) { this.say('hit'); this.seen.hits = S.hits | 0; } else this.seen.hits = Math.min(this.seen.hits, S.hits | 0);
    if (lv > this.lastLv) {
      for (let l = this.lastLv + 1; l <= lv; l++) this.lvBonus += E.lvBonus[l] || 0;
      this.lastLv = lv; this.maxLv = Math.max(this.maxLv, lv);
      this.marks.push({ t: this.t, k: 'lv', lv });
      this.say('lv' + Math.min(5, lv), { n: lv }); this.shot('lv' + lv, 30 + lv * 10);
    }
    if (heli && !this.heliSeen) { this.heliSeen = true; this.say('heli'); this.shot('heli', 70); }
    if (kmh >= 200 && !this.m200) { this.m200 = true; this.say('fast200', { n: Math.round(kmh / 5) * 5 }); }
    if (kmh >= 250 && !this.m250) { this.m250 = true; this.say('fast250', { n: Math.round(kmh / 5) * 5 }); this.shot('fast', 52); }
    if (!this.droveShot && this.t > 25) { this.droveShot = true; this.shot('drive', 10); }
    // places and weather
    const zt = g.zoneType || 'highway';
    if (zt !== this.lastZone) {
      this.lastZone = zt;
      if (this.t - (this.cmT.zone ?? -99) > 40 && Math.random() < 0.7) { this.cmT.zone = this.t; this.say('z_' + (zt === 'seabridge' ? 'bridge' : zt)); }
    }
    if (this.curWx && this.curWx !== this.lastWx) { this.lastWx = this.curWx; if (this.curWx !== 'clear') this.say('w_' + this.curWx); }
    // idle chatter: a busy room talks more; the people who piled onto an event arrive a few seconds late
    if (this.t > this.cmNext) {
      this.cmNext = this.t + (20 + Math.random() * 26) / (1 + Math.min(3, this.viewers / 400) * 0.6);
      const eng = this.g.profile.car().eng;
      if (Math.random() < 0.3) this.say('eng_' + eng); else this.say('idle');
    }
    for (let i = this.pend.length - 1; i >= 0; i--) if (this.pend[i].at <= this.t) { const p = this.pend.splice(i, 1)[0]; this.mk(p.kind, p.o); }
    // audience
    const target = (25 + 380 * Math.pow(Math.max(0, this.hs), 1.1)) * (1 + Math.sqrt(this.fans) / 60);
    this.hs = approach(this.hs, this.hype, 0.25, dt);
    this.viewers = approach(this.viewers, target, 0.17, dt);
    if (this.viewers > this.peak) this.peak = this.viewers;
    this.views += this.viewers * dt / 22;
    this.curveT += dt;
    if (this.curveT >= this.curveDt) {
      this.curveT = 0; this.curve.push([this.t, this.viewers * (0.97 + Math.random() * 0.06)]);
      if (this.curve.length > 600) { this.curve = this.curve.filter((q, i) => i % 2 === 0); this.curveDt *= 2; }
    }
  }
  envHype(g, dt) {
    const E = ECON, W = g.weather;
    const zt = g.zoneType || 'highway';
    const wc = W.snow > 0.25 ? 'snow' : W.thunder > 0.4 ? 'thunder' : W.rain > 0.3 ? 'rain' : W.fog > 0.35 ? 'fog' : 'clear';
    this.curWx = wc;
    this.zoneT[zt] = (this.zoneT[zt] || 0) + dt; this.wxT[wc] = (this.wxT[wc] || 0) + dt;
    const key = zt + '|' + wc, used = this.envT[key] = (this.envT[key] || 0) + dt;
    const raw = (E.zone[zt] || 0) + E.wx.rain * W.rain + E.wx.fog * W.fog + E.wx.snow * W.snow + E.wx.thunder * W.thunder;
    return raw * (0.3 + 0.7 * Math.exp(-used / E.envDecay));
  }
  // v80: civilian collisions (fed by Game.onEvent) are scored once the contact is over, by the worst severity it reached
  onImpact(e) {
    const o = e.obj; if (e.kind !== 'car' || !o || o.cop || o.prop) return;
    const sev = e.severity || 0, t = this.t;
    let c = this.civ.find((x) => x.o === o);
    if (c && !e.merged) { this.civDone(c); this.civ.splice(this.civ.indexOf(c), 1); c = null; }
    if (!c) { if (sev < 1.2) return; c = { o, t0: t, tl: t, sev }; this.civ.push(c); }
    c.tl = t; c.sev = Math.max(c.sev, sev);
  }
  civDone(c) {
    const C = ECON.civ, key = c.sev >= C.smash ? 'smash' : c.sev >= C.crash ? 'crash' : 'scrape';
    this.event(key, this.kmh, this.wmNow || 1);
    const L = this.chainL = this.chainL.filter((x) => c.t0 - x.t < C.chainT);
    if (!L.some((x) => x.o === c.o)) L.push({ o: c.o, t: c.t0 });
    if (L.length >= C.chainN) { this.chainL = []; this.event('chain', this.kmh, this.wmNow || 1); }
  }
  civTick(g, kmh, wm, lv) {
    this.wmNow = wm;
    for (let i = this.civ.length - 1; i >= 0; i--) if (this.t - this.civ[i].tl >= 0.5) { const c = this.civ[i]; this.civ.splice(i, 1); this.civDone(c); }
    // a pursuing cop held directly ahead (in the player's lane, close) for a while
    const F = ECON.copFront, P = g.player, pol = g.police, dt = this.t - (this.cfLast ?? this.t); this.cfLast = this.t;
    let ahead = false;
    if (lv > 0 && pol && pol.units && kmh > F.kmh) for (const u of pol.units) {
      const c = u.cop; if (!c || c.hp <= 0 || (c.mode !== 'chase' && c.mode !== 'wait')) continue;
      const ds = u.s - P.s; if (ds > F.s0 && ds < F.s1 && Math.abs(u.d - P.d) < F.dd) { ahead = true; break; }
    }
    if (ahead) { this.cfGap = 0; this.cfT += dt; if (this.cfT >= F.t) { this.cfT = 0; this.event('copFront', kmh, wm); } }
    else if ((this.cfGap += dt) > 1.2) this.cfT = 0;
  }
  event(key, kmh, wm) {
    const E = ECON, n = this.evN[key]++;
    let amt = E.ev[key] * Math.max(E.evFloor, Math.pow(E.evDecay, n)) * wm;
    if (key === 'nearMiss') amt *= clamp(kmh / 160, 0.7, 2);
    this.evAcc[key] += amt;
    if (key === 'nearMiss') { this.say('nearMiss'); if (kmh > 150) this.shot('nm', 50); }
    else if (key === 'copsDown') { this.say('copsDown'); this.say('copsDown2'); this.shot('cop', 60); }
    else if (key === 'escapes') { this.say('escape'); this.shot('esc', 55); }
    else if (key === 'chain') { this.say('chain'); this.shot('chain', 55); }
    else if (key === 'copFront') this.say('copFront');
    else if (key === 'smash') this.shot('smash', 45);
  }
  // ---------------------------------------------------------------- the chat (nothing is shown while driving)
  chan() { try { return this.g.profile.data.name || '夜行记录仪'; } catch (e) { return '夜行记录仪'; } }
  ctx(o) {
    let car = null; try { car = this.g.profile.car(); } catch (e) { }
    return Object.assign({ n: Math.round(this.kmh || 0), cn: car ? car.cn || car.name.split(' ')[0] : '', short: car ? car.name.split(' ')[0] : '', car: car ? car.name : '', eng: car ? car.layout : '', engTxt: car ? car.engTxt : '' }, o || {});
  }
  person(name) {
    let p = this.ppl[name];
    if (!p) { const r = Math.random(); p = this.ppl[name] = { name, lv: r < 0.04 ? 1 : r < 0.16 ? 2 : r < 0.38 ? 3 : r < 0.66 ? 4 : r < 0.9 ? 5 : 6, vip: Math.random() < 0.12 }; }
    return p;
  }
  who() {
    if (this.regs.length && Math.random() < 0.15) { const r = cmPick(this.regs); if ((this.regN[r] = (this.regN[r] || 0) + 1) <= 3) return r; }
    return cmNick(this.used);
  }
  say(kind, o, force) {
    const pool = CM[kind]; if (!pool) return null;
    const gap = CM_GAP[kind] ?? 0, last = this.cmT[kind] ?? -9999;
    if (!force && this.t - last < gap) return null;
    this.cmT[kind] = this.t;
    const c = this.mk(kind, o);
    // others pile on a few seconds later (a quiet room does not)
    const mx = CM_BURST[kind] || 0, n = mx ? Math.min(mx, Math.floor(Math.random() * (mx + 1) * Math.min(1, 0.3 + (this.viewers || 20) / 260))) : 0;
    for (let i = 0; i < n; i++) this.pend.push({ at: this.t + 1.2 + Math.random() * 6 + i * 0.9, kind, o });
    return c;
  }
  mk(kind, o) {
    const pool = CM[kind]; if (!pool) return null;
    const cx = this.ctx(o);
    let text = cmFill(cmPick(pool), cx);
    for (let k = 0; k < 5 && this.said.has(text); k++) text = cmFill(cmPick(pool), cx);
    this.said.add(text);
    const pe = this.person(this.who());
    const c = { t: this.t, kind, name: pe.name, lv: pe.lv, vip: pe.vip, text: cmJitter(text), tc: Math.random() < (CM_TC[kind] || 0) ? this.t : -1, sub: [], subN: 0 };
    this.cm.push(c);
    if (this.cm.length > 110) this.cm.splice(2 + Math.floor(Math.random() * (this.cm.length - 6)), 1);
    this.reply(c, cx);
    return c;
  }
  // replies under a comment: only other viewers. The driver never talks, so there is no author reply anywhere.
  reply(c, cx) {
    const grp = CM_GROUP[c.kind] || 'idle';
    let q = '';
    if (/什么车|啥车|多少钱/.test(c.text)) q = 'q_car';
    else if (/哪条路|去哪|哪座/.test(c.text)) q = 'q_road';
    else if (/记录仪|镜头|画质/.test(c.text)) q = 'q_cam';
    else if (/开麦|不说话|没有解说|没声音|放首歌|怎么不放歌/.test(c.text)) q = 'q_mic';
    let nv = Math.random() < (q ? 0.5 : 0.42) ? 1 + (Math.random() < 0.35 ? 1 : 0) + (Math.random() < 0.12 ? 1 : 0) : 0;
    let tt = c.t;
    for (let i = 0; i < nv; i++) {
      const pool = q && CM_RP[q] ? CM_RP[q] : (Math.random() < 0.6 && CM_RP[grp] ? CM_RP[grp] : CM_RP.gen);
      const pe = this.person(this.who());
      tt += 4 + Math.random() * 40;
      c.sub.push({ t: tt, name: pe.name, lv: pe.lv, vip: pe.vip, text: cmJitter(cmFill(cmPick(pool), cx)), to: i && Math.random() < 0.4 ? c.sub[i - 1].name : '' });
    }
    if (c.sub.length) c.subN = c.sub.length + (Math.random() < 0.25 ? Math.floor(1 + Math.random() * 7) : 0);
  }
  // highlight screenshots: the game takes the picture after the next rendered frame (Game.takeSnap)
  shot(tag, prio) {
    const g = this.g;
    if (this.t - this.shotT < 6 && prio < 90) return;
    if (g.snapReq && g.snapReq.prio >= prio) return;
    this.shotT = this.t; g.snapReq = { tag, prio };
  }
  addSnap(url, tag, prio) {
    this.snaps.push({ url, tag, prio, t: this.t });
    this.snaps.sort((a, b) => b.prio - a.prio || b.t - a.t);
    if (this.snaps.length > 3) this.snaps.length = 3;
  }
  // ---------------------------------------------------------------- settlement
  makeTitle(kind, lv) {
    const g = this.g, top = Math.round(this.topKmh);
    if (this.t < 20) return '试播：只开了 ' + Math.round(this.t) + ' 秒';
    let wx = '夜路', best = '', bt = 0;
    for (const k in this.wxT) if (k !== 'clear' && this.wxT[k] > bt) { bt = this.wxT[k]; best = k; }
    if (bt > this.t * 0.25) wx = { rain: '雨夜', fog: '雾夜', snow: '雪夜', thunder: '雷雨夜' }[best] || '夜路';
    if (kind === 'arrest') return `${wx} ${top} km/h，被 ${Math.max(1, this.maxCops)} 台警车追到 ★${Math.max(1, lv)}`;
    if (kind === 'wreck') { const zn = ZONE_NAMES[g.zoneType] || ''; return `${wx} ${top} km/h，${zn}撞毁，直播被迫中断`; }
    return `${wx}安静夜驾 ${top} km/h，全程没被警察盯上`;
  }
  // the comment section as threads: likes, ages, replay visitors, what fits on the page
  threads(kind, views) {
    const end = this.t, gk = Math.max(1, views / 140);
    const lateN = views < 400 ? 1 + Math.floor(Math.random() * 2) : views < 3000 ? 2 + Math.floor(Math.random() * 2) : 3 + Math.floor(Math.random() * 3);
    this.t = end + 5;
    for (let i = 0; i < lateN; i++) { const c = this.mk('late'); if (c) { c.t = end + 5 + i * 20; c.late = true; } }
    this.t = end;
    let list = this.cm.slice().sort((a, b) => a.t - b.t);
    for (const c of list) {
      const early = c.t < 45 ? 1.6 : 1, pop = Math.pow(Math.random(), 3.2) * early * (CM_FUN[c.kind] || 1);
      c.likes = Math.round(pop * (14 + views * 0.03));
      for (const s of c.sub) s.likes = Math.round(Math.pow(Math.random(), 4) * (3 + c.likes * 0.2));
      if (c.tc >= 0) c.tc = Math.min(c.tc, end);
      c.ago = c.late ? '刚刚' : cmAgo(end - c.t + 20 + Math.random() * 40);
    }
    // what fits on the page: the first two, the last three, then whatever got the most likes
    const MAX = 14;
    if (list.length > MAX) {
      const keep = new Set([list[0], list[1], ...list.slice(-3)]);
      for (const c of list.slice().sort((a, b) => b.likes - a.likes)) { if (keep.size >= MAX) break; keep.add(c); }
      list = list.filter((c) => keep.has(c));
    }
    const hot = list.slice().sort((a, b) => b.likes - a.likes);
    if (hot[0] && hot[0].likes >= 8) hot[0].hot = true;
    if (hot[1] && hot[1].likes >= 40) hot[1].hot = true;
    return list;
  }
  // kind: 'arrest' | 'wreck' | 'quit'. Returns everything the upload page needs; the caller applies it to the profile.
  finish(kind) {
    const g = this.g, pf = g.profile, car = pf.car(), st = g.stats, E = ECON, A = this.acc;
    const lvEnd = Math.max(st.maxLevel | 0, this.maxLv);
    // last words, and whoever was still typing when the picture went away
    const t0 = this.t;
    this.say(kind, null, true); this.say(kind + '2', null, true);
    for (const p of this.pend) { this.t = t0 + 0.5 + Math.random() * 5; this.mk(p.kind, p.o); }
    this.pend = []; this.t = t0;
    this.curve.push([this.t, this.viewers]);
    this.marks.push({ t: this.t, k: 'end', kind });
    let kinds = 0;
    for (const k in this.zoneT) if (this.zoneT[k] >= E.div.zoneMin) kinds++;
    for (const k in this.wxT) if (k !== 'clear' && this.wxT[k] >= E.div.wxMin) kinds++;
    const divPct = Math.min(E.div.cap, E.div.per * Math.max(0, kinds - 1));
    for (const c of this.civ) this.civDone(c); this.civ = [];
    const ev = this.evAcc; let evSum = 0; for (const k in ev) evSum += ev[k];
    const divBonus = (A.base + A.speed + A.chase + A.env + evSum) * divPct;
    const lines = [];
    const add = (label, amt, note) => { if (amt >= 1) lines.push({ label, amt: Math.round(amt), note: note || '' }); };
    add('基础观众打赏', A.base, fmtTime(this.t) + ' 直播时长');
    add('速度与操作', A.speed, '最高 ' + Math.round(this.topKmh) + ' km/h');
    add('警方追捕', A.chase, lvEnd > 0 ? '最高 ' + wantedTxt(lvEnd) : '');
    add('场景与天气', A.env, '');
    add('惊险擦身', ev.nearMiss, '× ' + this.evN.nearMiss);
    add('撞停警车', ev.copsDown, '× ' + this.evN.copsDown);
    add('甩开追兵', ev.escapes, '× ' + this.evN.escapes);
    add('擦碰车辆', ev.scrape, '× ' + this.evN.scrape);
    add('撞击车辆', ev.crash, '× ' + this.evN.crash);
    add('猛烈撞击', ev.smash, '× ' + this.evN.smash);
    add('连环碰撞', ev.chain, '× ' + this.evN.chain);
    add('警车压在正前方', ev.copFront, '× ' + this.evN.copFront);
    add('通缉升级奖励', this.lvBonus, lvEnd > 0 ? '★' + lvEnd : '');
    add('场景多样性加成', divBonus, '+' + Math.round(divPct * 100) + '%');
    let tips = 0; for (const l of lines) tips += l.amt;
    let deductRaw = 0, deductLabel = '', deductNote = '';
    if (kind === 'arrest') { const L = Math.min(5, Math.max(1, lvEnd)); deductRaw = E.fine[L]; deductLabel = '罚款'; deductNote = wantedTxt(L); }
    else if (kind === 'wreck') {
      const val = pf.valueOf(car.id);
      const W = (this.g.player && this.g.player.wreckInfo) || {}, R = E.repair;
      const hp0 = clamp(W.hpBefore ?? 0, 0, 100), frame = 1 - hp0 / 100;
      const crashK = W.cause === 'catastrophic_impact' ? smooth(R.sev0, R.sev1, W.severity || 0) : 0;
      const rate = R.base + R.frame * frame + R.crash * crashK;
      const valR = E.repairRef * Math.pow(Math.max(1, val / E.repairRef), E.repairExp);
      deductRaw = Math.max(E.repairMin, Math.round((valR * rate + R.labour) / 50) * 50); deductLabel = '车辆维修';
      deductNote = car.name + ' 估值 ' + fmtMoney(val) + ' · 撞击 ' + Math.round((W.imp || 0) * 3.6) + ' km/h · 撞前车况 ' + Math.round(hp0) + '%';
    }
    const avail = pf.data.money + tips;
    const deduct = Math.min(deductRaw, avail), net = tips - deduct, balance = pf.data.money + net;
    const thumbs = this.snaps.map((s) => s.url);
    const views = Math.round(this.views), thr = this.threads(kind, views);
    let nSub = 0; for (const c of thr) nSub += Math.max(c.subN || 0, c.sub.length);
    const cmCount = thr.length + nSub + Math.round(views * (0.004 + 0.006 * Math.random()));
    return {
      kind, car: car.name, carCn: car.cn || '', title: this.makeTitle(kind, lvEnd), time: this.t, dist: st.dist, top: Math.round(this.topKmh), maxLevel: lvEnd,
      lines, tips, deductRaw, deduct, deductLabel, deductNote, net, balance,
      peak: Math.round(this.peak), views, likes: Math.round(this.views * (0.05 + 0.04 * Math.random())),
      fansGain: Math.round(this.peak * 0.18 + this.views * 0.06), kinds, divPct,
      comments: thr, cmCount, chan: this.chan(), curve: this.curve, marks: this.marks, cover: thumbs[0] || '', thumbs,
    };
  }
}

// ---- 12d_lot.js ----
// ============================================================================
//  Out-of-game screens: the ECHO creator studio (live / garage / account / settings) drawn over the 3-D showroom
//  (the car on the turntable is rendered into the main canvas behind the menu) and the signal-link overlay.
//  The upload page that settles a finished stream lives in 12e_upload.js.
// ============================================================================
function domEl(tag, cls, text) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text != null) e.textContent = text;
  return e;
}
function agoTxt(t) {
  const m = Math.max(0, (Date.now() - t) / 60000);
  if (m < 1) return '刚刚';
  if (m < 60) return Math.floor(m) + ' 分钟前';
  const h = m / 60;
  if (h < 24) return Math.floor(h) + ' 小时前';
  return Math.floor(h / 24) + ' 天前';
}
// linear paint colour -> css colour for the swatches
function paintCss(c) {
  const f = (x) => Math.round(255 * Math.pow(clamp(x, 0, 1), 0.4545));
  return 'rgb(' + f(c[0]) + ',' + f(c[1]) + ',' + f(c[2]) + ')';
}
function countUp(el, to, ms, fmt) {
  const t0 = performance.now();
  const step = (now) => {
    if (!el.isConnected) return;
    const k = Math.min(1, (now - t0) / ms), e = 1 - Math.pow(1 - k, 3);
    el.textContent = fmt(to * e);
    if (k < 1) requestAnimationFrame(step); else el.textContent = fmt(to);
  };
  el.textContent = fmt(0);
  requestAnimationFrame(step);
}
// the stat panel: normalised bars (white = what the car has now, red = what the turbo kit would add) + the real numbers
function statRows(car, turbo) {
  const a = carSpec(car, false), b = car.turboOk ? carSpec(car, true) : a, c = turbo && car.turboOk ? b : a;
  const t100 = (s) => s.t100 || 1100 / (s.hp / (s.mass / 1000));   // v81: a car can quote its own figure (the hybrid's motor)    // rule-of-thumb 0-100 km/h time from the power-to-weight ratio
  const defs = [
    ['POWER', '最大功率', (s) => s.hp / 520, (s) => fmtNum(s.hp), 'HP'],
    ['TORQUE', '最大扭矩', (s) => s.nm / 650, (s) => fmtNum(s.nm), 'N·M'],
    ['0–100', '百公里加速', (s) => (9 - t100(s)) / 5.5, (s) => t100(s).toFixed(1), 'S'],
    ['TOP SPEED', '极速', (s) => s.top / 320, (s) => fmtNum(s.top), 'KM/H'],
    ['WEIGHT', '整备质量', (s) => s.mass / 2000, (s) => fmtNum(s.mass), 'KG'],
  ];
  return defs.map(([en, cn, f, v, unit]) => ({
    en, cn, unit, val: v(c),
    w: Math.round(clamp(f(c), 0.04, 1) * 100), p: Math.round(clamp(Math.max(f(c), f(b)), 0.04, 1) * 100),
  }));
}
// camera of the showroom per page. shift: where the car's centre sits (NDC x); frac: car length / picture width
const LOT_CAM = {
  live: { shift: 0.10, frac: 0.47, el: 0.12, ty: 0.58, dim: 1 },
  garage: { shift: 0.08, frac: 0.41, el: 0.14, ty: 0.58, dim: 1 },
  acct: { shift: 0.58, frac: 0.50, el: 0.10, ty: 0.60, dim: 0.45 },
  set: { shift: 0.58, frac: 0.50, el: 0.10, ty: 0.60, dim: 0.45 },
};
const LOT_TABS = ['live', 'garage', 'acct', 'set'];
const LOT_WORD = { live: 'On Air', garage: 'Garage', acct: 'Creator', set: 'Settings' };
const CARD_VIEW = { fov: 0.5, frac: 0.8, el: 0.14 };

class Lot {
  constructor(g) {
    this.g = g; this.pf = g.profile;
    this.$ = (id) => document.getElementById(id);
    this.tabName = 'live'; this.view = this.pf.data.cur; this.pvPaint = '';
    this.yaw = 0.62; this.idle = 0; this.drag = null; this.hot = null;
    this.msgTm = 0; this.linkTm = 0; this.rstTm = 0; this.rstArm = false;
    this.t = 0; this.cam = Object.assign({}, LOT_CAM.live); this.disp = null; this.slide = null; this.pend = []; this.cardEls = null; this.warmT = 0.7;
    this.up = new UploadPage(this);
    this.forum = new ForumView(this);
    const root = this.$('lot');
    for (const b of document.querySelectorAll('#lotTabs button[data-tab]')) b.onclick = () => this.tab(b.dataset.tab);
    this.$('bGo').onclick = () => g.startRun();
    this.$('bResetLot').onclick = () => g.ui.resetSettings();
    this.$('bExp').onclick = () => this.exportSave();
    this.$('bImp').onclick = () => this.$('impFile').click();
    this.$('impFile').onchange = (ev) => this.importSave(ev);
    this.$('bRst').onclick = () => this.resetClick();
    // a clicked button must not keep the keyboard focus (Enter belongs to the page's main action)
    root.addEventListener('click', (ev) => { const b = ev.target.closest && ev.target.closest('button'); if (b) setTimeout(() => b.blur(), 0); });
    const dr = this.$('lotDrag');
    dr.onpointerdown = (ev) => { this.drag = { x: ev.clientX, yaw: this.yaw }; this.idle = 0; try { dr.setPointerCapture(ev.pointerId); } catch (e) { } };
    dr.onpointermove = (ev) => { if (this.drag) { this.yaw = this.drag.yaw + (ev.clientX - this.drag.x) * 0.012; this.idle = 0; } };
    dr.onpointerup = () => { this.drag = null; this.idle = 0; };
    dr.onpointercancel = dr.onpointerup;
    window.addEventListener('keydown', (e) => this.onKey(e));
  }
  onKey(e) {
    if (this.g.mode !== 'lot' || this.g.starting || !this.$('lot').classList.contains('show')) return;
    const tg = e.target && e.target.tagName;
    if (tg === 'INPUT' || tg === 'TEXTAREA' || tg === 'SELECT' || e.ctrlKey || e.metaKey || e.altKey) return;
    const c = e.code;
    if (this.forum.isOpen) { if (this.forum.key(e)) e.preventDefault(); return; }
    if (c === 'KeyQ' || c === 'KeyE') {
      if (!e.repeat) this.tab(LOT_TABS[(LOT_TABS.indexOf(this.tabName) + (c === 'KeyE' ? 1 : LOT_TABS.length - 1)) % LOT_TABS.length]);
      e.preventDefault();
    } else if ((c === 'ArrowLeft' || c === 'ArrowRight') && this.tabName === 'garage') {
      this.step(c === 'ArrowRight' ? 1 : -1); e.preventDefault();
    } else if ((c === 'Enter' || c === 'NumpadEnter') && !e.repeat) {
      if (tg === 'BUTTON' && document.activeElement === e.target) return;
      this.enter(); e.preventDefault();
    }
  }
  // Enter: start the stream (live page) / buy or equip the car on display (garage page)
  enter() {
    if (this.tabName === 'live') this.g.startRun();
    else if (this.tabName === 'garage') { const b = this.$('gBuy').querySelector('button.primary'); if (b) b.click(); }
  }
  step(dir) {
    const i = CARS.findIndex((c) => c.id === this.view);
    this.view = CARS[(i + dir + CARS.length) % CARS.length].id; this.pvPaint = ''; this.idle = 0; this.g.uiA.sfx('swish');
    this.renderGarage();
  }
  show() {
    this.view = this.pf.data.cur; this.pvPaint = ''; this.hot = null; this.disp = null; this.slide = null;
    this.$('lot').classList.add('show');
    this.g.ui.buildSettings();
    this.tab('live');
  }
  hide() { this.forum.close(true); this.$('lot').classList.remove('show'); }
  tab(name) {
    this.forum.close(true);
    this.g.uiA.sfx('tab', LOT_TABS.indexOf(name));
    this.tabName = name;
    this.disarmReset();
    const root = this.$('lot');
    root.dataset.pg = name;
    for (const b of document.querySelectorAll('#lotTabs button[data-tab]')) b.classList.toggle('on', b.dataset.tab === name);
    for (const id of LOT_TABS) {
      const pg = this.$('pg' + id.charAt(0).toUpperCase() + id.slice(1));
      if (pg) pg.classList.toggle('on', id === name);
    }
    this.$('bgWordTx').textContent = LOT_WORD[name];
    this.$('kbCar').style.display = name === 'garage' ? '' : 'none';
    this.$('kbDrag').style.display = name === 'live' || name === 'garage' ? '' : 'none';
    const en = this.$('kbEnter');
    en.parentNode.style.display = name === 'live' || name === 'garage' ? '' : 'none';
    en.textContent = name === 'garage' ? '购买 / 设为座驾' : '开始直播';
    this.idle = 0;
    this.refresh();
  }
  refresh() {
    const d = this.pf.data;
    this.$('lChan').textContent = d.name;
    this.$('lFans').textContent = fmtFans(d.fans);
    this.$('lMoney').textContent = fmtMoney(d.money);
    if (this.tabName === 'live') this.renderLive();
    else if (this.tabName === 'garage') this.renderGarage();
    else if (this.tabName === 'acct') this.renderAcct();
  }
  flash(msg, ok) {
    const m = this.$('lotMsg'); if (!m) return;
    this.g.uiA.sfx(ok === false ? 'bad' : 'ok');
    m.textContent = msg; m.className = (ok === false ? 'bad' : 'ok') + ' on';
    clearTimeout(this.msgTm);
    this.msgTm = setTimeout(() => { m.className = ''; }, 2600);
  }
  // result of a purchase / change in the garage
  act(r) {
    this.flash(r.msg, r.ok);
    if (r.ok) this.g.syncCarSet();
    this.refresh();
  }
  // "signal link" overlay shown while the next stream is being set up
  link(on) {
    const s = this.$('linkScr'), t = this.$('lkS');
    clearInterval(this.linkTm);
    if (!s) return;
    if (on) {
      const L = ['正在连接 ECHO 直播服务器', '分配推流通道', '校准记录仪时钟', '信号接入'];
      let i = 0;
      if (t) t.textContent = L[0];
      this.g.uiA.sfx('link');
      s.classList.add('show');
      this.linkTm = setInterval(() => { i = Math.min(L.length - 1, i + 1); if (t) t.textContent = L[i]; }, 520);
    } else s.classList.remove('show');
  }
  setCover(url) { this.up.setCover(url); }
  renderUpload(st, res) { this.up.render(st, res); }
  // ---------------------------------------------------------------- shared bits
  setName(id, car) {
    const parts = car.name.split(' ');
    this.$(id).innerHTML = escHtml(parts[0]) + (parts.length > 1 ? '<small>' + escHtml(parts.slice(1).join(' ')) + '</small>' : '');
  }
  // bars are updated in place so they slide when the car changes
  setStats(el, car, turbo) {
    const rows = statRows(car, turbo);
    if (el.children.length !== rows.length) {
      el.innerHTML = rows.map((r) => '<div class="sb"><div class="sbL">' + r.en + '<small>' + r.cn + '</small></div><div class="bar"><u></u><b></b></div><div class="sbV"><span></span><small>' + r.unit + '</small></div></div>').join('');
      void el.offsetWidth;
    }
    rows.forEach((r, i) => {
      const row = el.children[i];
      row.querySelector('.bar b').style.width = r.w + '%'; row.querySelector('.bar u').style.width = r.p + '%';
      row.querySelector('.sbV span').textContent = r.val;
    });
  }
  // ---------------------------------------------------------------- live page
  renderLive() {
    const pf = this.pf, d = pf.data, car = pf.car(), st = pf.st(car.id) || {};
    this.setName('liveName', car);
    this.$('liveEng').textContent = car.layout;
    this.$('liveSub').textContent = [car.cn, car.engTxt].filter(Boolean).join(' · ') + (st.turbo ? ' + 涡轮' : '');
    this.setStats(this.$('liveSpec'), car, !!st.turbo);
    const pn = PAINT_OPTS.find((p) => p[0] === (st.paint || 'black')) || PAINT_OPTS[0];
    const ups = [];
    if (car.dct) ups.push('<span class="chip on">8 速双离合</span>');
    else ups.push('<span class="chip' + (st.seq ? ' on' : '') + '">' + (st.seq ? '序列式变速箱' : '原厂变速箱') + '</span>');
    if (car.stockTurbo) ups.push('<span class="chip on">双涡轮增压</span>');
    if (car.hybrid) ups.push('<span class="chip on">混合动力</span>');
    if (car.turboOk) ups.push('<span class="chip' + (st.turbo ? ' on' : '') + '">' + (st.turbo ? '涡轮增压' : '自然吸气') + '</span>');
    ups.push('<span class="chip"><i style="background:' + paintCss(pn[2]) + '"></i>' + pn[1] + '</span>');
    this.$('liveUp').innerHTML = ups.join('');
    // recent streams
    const rc = this.$('liveRecent'); rc.innerHTML = '';
    if (!d.last.length) rc.appendChild(domEl('div', 'empty', '还没有直播记录。点“开始直播”，把今晚的夜路发上论坛。'));
    for (const l of d.last) {
      const row = domEl('div', 'rItem');
      const th = domEl('div', 'rThumb');
      if (l.thumb) { const im = new Image(); im.src = l.thumb; th.appendChild(im); } else th.textContent = 'NO IMAGE';
      const mid = domEl('div', 'rMid');
      mid.appendChild(domEl('div', 'rTitle', l.title || '未命名直播'));
      mid.appendChild(domEl('div', 'rSub', (l.car || '') + ' · ' + agoTxt(l.t) + (l.top ? ' · 最高 ' + l.top + ' km/h' : '')));
      const kd = { arrest: ['被截停', 'bad'], wreck: ['撞毁', 'bad'], quit: ['平安收工', 'ok'] }[l.kind] || ['', ''];
      const rt = domEl('div', 'rEnd');
      rt.appendChild(domEl('b', l.net >= 0 ? 'pos' : 'neg', (l.net >= 0 ? '+' : '') + fmtMoney(l.net)));
      rt.appendChild(domEl('span', 'tag ' + kd[1], kd[0]));
      row.appendChild(th); row.appendChild(mid); row.appendChild(rt);
      row.onclick = () => this.forum.openStream(l);
      rc.appendChild(row);
    }
    // forum hot threads: click to read the post and the replies
    if (!this.hot) {
      const pool = FORUM.slice(), pick = [];
      while (pick.length < 4 && pool.length) pick.push(pool.splice(Math.floor(Math.random() * pool.length), 1)[0]);
      this.hot = pick;
    }
    const hp = this.$('liveHot'); hp.innerHTML = '';
    for (const p of this.hot) {
      const row = domEl('div', 'hItem' + (this.forum.seen.has(p.t) ? ' seen' : ''));
      row.appendChild(domEl('span', 'hBoard', p.b));
      row.appendChild(domEl('span', 'hTitle', p.t));
      row.appendChild(domEl('span', 'hRep', p.n + ' 回帖'));
      row.onclick = () => { row.classList.add('seen'); this.forum.openThread(p); };
      hp.appendChild(row);
    }
  }
  // ---------------------------------------------------------------- garage page
  renderGarage() {
    const pf = this.pf, d = pf.data, c = carById(this.view), st = pf.st(c.id), cur = d.cur === c.id;
    const key = this.pvPaint || (st ? st.paint : 'black');
    this.setName('gName', c);
    this.$('gEng').textContent = c.layout;
    this.$('gSub').textContent = [c.cn, c.engTxt].filter(Boolean).join(' · ') + (st && st.turbo ? ' + 涡轮' : '');
    this.setStats(this.$('gSpec'), c, !!(st && st.turbo));
    this.$('gBlurb').textContent = c.blurb;
    // paint
    const gp = this.$('gPaint'); gp.innerHTML = '';
    for (const p of PAINT_OPTS) {
      const k = p[0], own = !!st && pf.paintOwned(c.id, k), price = paintPrice(c, k);
      const label = own ? (st.paint === k ? '使用中' : '已拥有') : (price ? fmtMoney(price) : '免费');
      const b = domEl('button', 'sw' + (k === key ? ' on' : '') + (st && st.paint === k ? ' cur' : ''));
      b.innerHTML = '<i style="background:' + paintCss(p[2]) + '"></i><span>' + p[1] + '</span><em>' + label + '</em>';
      b.onclick = () => { this.pvPaint = k; this.idle = 0; this.renderGarage(); };
      gp.appendChild(b);
    }
    if (st && key !== st.paint) {
      const own = pf.paintOwned(c.id, key), price = paintPrice(c, key);
      const b = domEl('button', 'act' + (!own && d.money < price ? ' dis' : ''), own ? '换上此车漆' : '购买并喷涂 ' + fmtMoney(price));
      b.onclick = () => { const r = pf.buyPaint(c.id, key); if (r.ok) this.pvPaint = ''; this.act(r); };
      gp.appendChild(b);
    }
    // upgrades: two stages
    const gu = this.$('gUp'); gu.innerHTML = '';
    const upRow = (n, kind, name, desc, price, has, avail, emT) => {
      const row = domEl('div', 'upRow' + (has ? ' has' : '') + (avail ? '' : ' lock'));
      const sg = domEl('div', 'stg', String(n)); sg.appendChild(domEl('small', '', 'STAGE'));
      const tx = domEl('div', 'upTx');
      tx.appendChild(domEl('b', '', name)); tx.appendChild(domEl('span', '', desc));
      row.appendChild(sg); row.appendChild(tx);
      if (!avail) row.appendChild(domEl('em', has ? 'done' : 'na', has ? emT || '原厂标配' : '不适用'));
      else if (has) row.appendChild(domEl('em', 'done', '已安装'));
      else {
        const b = domEl('button', 'act' + (!st || d.money < price ? ' dis' : ''), fmtMoney(price));
        b.onclick = () => this.act(st ? pf.buyUp(c.id, kind) : { ok: false, msg: '先购入这台车' });
        row.appendChild(b);
      }
      gu.appendChild(row);
    };
    if (c.noUp) {   // v81 XH-6: everything comes from the factory, nothing to fit
      upRow(1, 'seq', '8 速双离合变速箱', '两组离合器交替接合，换挡几乎不断动力', 0, true, false, '原厂已配备');
      upRow(2, 'turbo', '双涡轮 + 电机', '直六双涡轮配前轴电机，补足起步和低转推力', 0, true, false, '原厂已配备');
    } else {
    upRow(1, 'seq', '序列式变速箱', '快速断火换挡，手动挡更干脆', c.seqPrice, !!(st && st.seq), true);
    if (c.stockTurbo) upRow(2, 'turbo', '顺序式双涡轮', '原厂配置：小涡轮低转先介入，约 4500 rpm 切换大涡轮', 0, true, false);
    else upRow(2, 'turbo', '涡轮增压套件', c.turboOk ? '加装单涡轮，推力更猛，但有迟滞' : '这台车没有可用的涡轮套件', c.turboPrice, !!(st && st.turbo), c.turboOk);
    }
    // buy / set as the daily driver
    const gb = this.$('gBuy'); gb.innerHTML = '';
    if (!st) {
      const can = d.money >= c.price;
      if (!can) gb.appendChild(domEl('div', 'hintL', '还差 ' + fmtMoney(c.price - d.money)));
      const b = domEl('button', 'primary' + (can ? '' : ' dis'), '购入  ' + fmtMoney(c.price));
      b.onclick = () => { const r = pf.buyCar(c.id); if (r.ok) { this.view = c.id; this.pvPaint = ''; } this.act(r); };
      gb.appendChild(b);
    } else if (!cur) {
      const b = domEl('button', 'primary', '设为座驾');
      b.onclick = () => this.act(pf.setCur(c.id));
      gb.appendChild(b);
    } else gb.appendChild(domEl('div', 'curTag', '当前座驾'));
    this.renderCards();
  }
  // the three car cards along the bottom (built once, updated in place; the pictures arrive from the warm-up queue)
  renderCards() {
    const gc = this.$('gCards'), pf = this.pf, d = pf.data;
    if (!this.cardEls) {
      this.cardEls = {}; gc.innerHTML = '';
      for (const car of CARS) {
        const b = domEl('button', 'cCard');
        const nm = car.name.split(' ');
        b.innerHTML = '<img alt="" draggable="false" style="display:none"><div class="cShade"></div><div class="cTop"></div><div class="cCls">' + escHtml(car.cls) + '</div>'
          + '<div class="cTx"><b>' + escHtml(nm[0]) + '</b><span>' + escHtml([car.cn, car.layout].filter(Boolean).join(' · ')) + '<em></em></span></div>';
        b.onclick = () => { if (this.view !== car.id) { this.view = car.id; this.pvPaint = ''; this.idle = 0; } this.renderGarage(); };
        gc.appendChild(b);
        this.cardEls[car.id] = b;
      }
    }
    for (const car of CARS) {
      const b = this.cardEls[car.id], s = pf.st(car.id), curr = d.cur === car.id;
      b.classList.toggle('on', car.id === this.view);
      const em = b.querySelector('em');
      em.textContent = s ? (curr ? '当前座驾' : '已拥有') : (car.price ? fmtMoney(car.price) : '免费');
      em.className = s ? (curr ? 'cur' : 'own') : '';
      this.cardPic(car);
    }
    this.paintCards();
  }
  cardPic(car) {
    const sr = this.g.showroom, s = this.pf.st(car.id), paint = s ? s.paint : 'black';
    const key = car.id + '|' + paint + '|480|card';
    if (sr.photos[key] === undefined && !this.pend.some((q) => q[2] === key)) this.pend.push([car, paint, key]);
    return sr.photos[key] || '';
  }
  paintCards() {
    if (!this.cardEls) return;
    const sr = this.g.showroom;
    for (const car of CARS) {
      const s = this.pf.st(car.id), url = sr.photos[car.id + '|' + (s ? s.paint : 'black') + '|480|card'] || '';
      const im = this.cardEls[car.id].querySelector('img');
      if (url) { if (im.getAttribute('src') !== url) im.src = url; im.style.display = ''; } else im.style.display = 'none';
    }
  }
  // ---------------------------------------------------------------- the turntable (called every frame while the lot is up)
  warm(sr, dt) {
    this.warmT -= dt;
    if (this.warmT > 0 || this.slide) return;
    this.warmT = 0.3;
    for (const c of CARS) if (!sr.models[c.id]) { sr.model(c); return; }       // one expensive build per tick
    if (this.pend.length) {
      const [car, paint, key] = this.pend.shift();
      if (sr.photos[key] === undefined) sr.photo(car, paint, 480, 270, { yaw: 0.62, view: CARD_VIEW, tag: 'card' });
      this.paintCards();
    }
  }
  frame(dt, dry) {
    const g = this.g, sr = g.showroom, pf = this.pf, root = this.$('lot');
    if (!sr || sr.ok === false || !sr.init()) { root.classList.add('noGl'); return; }
    this.t += dt;
    this.warm(sr, dt);
    // what stands on the turntable
    const tab = this.tabName, onGarage = tab === 'garage';
    const wantId = onGarage ? this.view : pf.data.cur, sw = pf.st(wantId);
    const wantPaint = onGarage ? (this.pvPaint || (sw ? sw.paint : 'black')) : (sw ? sw.paint : 'black');
    if (!this.disp) this.disp = { id: wantId, paint: wantPaint };
    else if (this.disp.id !== wantId) {
      const ia = CARS.findIndex((c) => c.id === this.disp.id), ib = CARS.findIndex((c) => c.id === wantId);
      this.slide = { id: this.disp.id, paint: this.disp.paint, yaw: this.yaw, t: 0, dir: ib >= ia ? 1 : -1 };
      this.disp = { id: wantId, paint: wantPaint };
      this.yaw = 0.62; this.idle = 0; this.popT = 0;
    } else this.disp.paint = wantPaint;
    this.popT = (this.popT || 0) + dt;
    // camera preset (eased) and the car's heading
    const tg = LOT_CAM[tab] || LOT_CAM.live, cam = this.cam, kk = 1 - Math.exp(-Math.min(dt, 0.1) * 5);
    for (const k in tg) cam[k] += (tg[k] - cam[k]) * kk;
    if (!this.drag) {
      this.idle += dt;
      if (onGarage) { if (this.idle > 1.8) this.yaw += dt * 0.32; }
      else if (this.idle > 1.0) {
        const target = 0.62 + 0.30 * Math.sin(this.t * 0.35), dy = this.yaw - target;
        this.yaw = target + (dy - TAU * Math.round(dy / TAU)) * Math.exp(-dt * 1.4);
      }
    }
    const paintOf = (k) => (PAINT_OPTS.find((p) => p[0] === k) || PAINT_OPTS[0])[2];
    const pu = sat((this.popT - 0.75) / 0.5), items = [{ car: carById(this.disp.id), paint: paintOf(this.disp.paint), yaw: this.yaw, dx: 0, pop: pu * pu * (3 - 2 * pu) }];
    const o = { fov: 0.40, el: cam.el, frac: cam.frac, shift: cam.shift, ty: cam.ty, dim: cam.dim, lit: 1 };
    if (this.slide) {
      const s = this.slide; s.t += dt / 0.7;
      const e = 1 - Math.pow(1 - Math.min(1, s.t), 3), S = (sr.camInfo ? sr.camInfo.halfW : 6) * 2.5;
      items[0].dx = s.dir * S * (1 - e);
      items.push({ car: carById(s.id), paint: paintOf(s.paint), yaw: s.yaw, dx: -s.dir * S * e });
      if (s.t >= 1) this.slide = null;
    }
    if (dry) return;    // test hook: advance the animation without drawing
    const cw = gl.drawingBufferWidth, ch = gl.drawingBufferHeight;
    const k = Math.min(1, Math.sqrt(2.6e6 / (cw * ch)));
    const ok = sr.scene(Math.round(cw * k), Math.round(ch * k), items, o);
    if (ok) { sr.present(cw, ch); root.classList.remove('noGl'); } else root.classList.add('noGl');
  }
  // ---------------------------------------------------------------- account page
  renderAcct() {
    const t = this.pf.data.tot;
    const tiles = [
      ['累计直播', fmtNum(t.runs) + ' 场'], ['累计打赏', fmtMoney(t.tips)], ['累计罚款', fmtMoney(t.fines)], ['累计维修', fmtMoney(t.repair)],
      ['总里程', t.km.toFixed(1) + ' km'], ['总时长', fmtTime(t.time)], ['最高车速', fmtNum(t.top) + ' km/h'], ['最高通缉', t.maxLevel > 0 ? '★'.repeat(t.maxLevel) : '—'],
      ['峰值同时在线', fmtNum(t.peak)], ['被截停', fmtNum(t.arrests) + ' 次'], ['撞毁', fmtNum(t.wrecks) + ' 次'], ['平安收工', fmtNum(t.quits) + ' 次'],
    ];
    this.$('acctGrid').innerHTML = tiles.map((q) => '<div class="tile"><span>' + q[0] + '</span><b>' + q[1] + '</b></div>').join('');
    this.$('acctNote').textContent = '存档保存在这台设备的浏览器里。换设备或清理浏览器数据之前，请先导出存档。';
  }
  exportSave() {
    try {
      const blob = new Blob([this.pf.exportText()], { type: 'application/json' });
      const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'echo-save.json';
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 4000);
      this.flash('已导出存档文件', true);
    } catch (e) { this.flash('导出失败', false); }
  }
  importSave(ev) {
    const f = ev.target.files && ev.target.files[0];
    ev.target.value = '';
    if (!f) return;
    const rd = new FileReader();
    rd.onload = () => {
      if (this.pf.importText(String(rd.result || ''))) {
        this.g.syncCarSet(); this.view = this.pf.data.cur; this.pvPaint = '';
        this.flash('存档已导入', true); this.refresh();
      } else this.flash('存档文件无法识别', false);
    };
    rd.onerror = () => this.flash('读取文件失败', false);
    rd.readAsText(f);
  }
  resetClick() {
    const b = this.$('bRst');
    if (!this.rstArm) {
      this.rstArm = true; b.textContent = '再点一次：清空全部存档'; b.classList.add('warn');
      clearTimeout(this.rstTm); this.rstTm = setTimeout(() => this.disarmReset(), 3500);
      return;
    }
    this.disarmReset();
    this.pf.reset(); this.g.syncCarSet(); this.view = this.pf.data.cur; this.pvPaint = '';
    this.flash('存档已重置', true); this.refresh();
  }
  disarmReset() {
    this.rstArm = false; clearTimeout(this.rstTm);
    const b = this.$('bRst'); if (b) { b.textContent = '重置存档'; b.classList.remove('warn'); }
  }
}

