// ---------------------------------------------------------------- helpers
const fmHash = (s) => { let h = 7; s = String(s); for (let i = 0; i < s.length; i++) h = (Math.imul(h, 33) + s.charCodeAt(i)) >>> 0; return h; };
function fmRng(seed) {
  return () => { seed = (seed + 0x6D2B79F5) >>> 0; let t = seed; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}
const fmAgo = (m) => (m < 1 ? '刚刚' : m < 60 ? Math.round(m) + ' 分钟前' : m < 1440 ? Math.floor(m / 60) + ' 小时前' : Math.floor(m / 1440) + ' 天前');
// a nickname always has the same level, so the same person looks the same in every thread
function fmLv(name) { const r = (fmHash(name) % 1000) / 1000; return r < 0.04 ? 1 : r < 0.16 ? 2 : r < 0.38 ? 3 : r < 0.66 ? 4 : r < 0.9 ? 5 : 6; }
const fmVip = (name) => fmHash(name + 'v') % 9 === 0;

class ForumView {
  constructor(lot) {
    this.lot = lot; this.$ = lot.$; this.isOpen = false; this.tm = 0; this.cache = {}; this.seen = new Set();
    this.$('thrX').onclick = () => this.close();
    this.$('thr').querySelector('.thrBg').onclick = () => this.close();
  }
  // ---- data -> a post the sheet can draw
  fromThread(p) {
    const rnd = fmRng(fmHash(p.t));
    // the first answers arrive quickly, the rest trickle in until the page was opened
    let off = 3 + rnd() * 30;
    const re = p.re.map((r) => {
      off += (p.age * 0.5 / p.re.length) * (0.3 + rnd() * 1.4);
      return { name: r[0], text: r[1], likes: r[2], q: r[3], ago: Math.max(2, p.age - Math.min(off, p.age - 2)) };
    });
    return {
      kind: 'thread', key: 't' + p.t, title: p.t, board: p.b, au: p.au, vip: !!p.vip, lv: fmLv(p.au), age: p.age, n: p.n, body: p.body, re,
      views: Math.round(p.n * (26 + rnd() * 34)), likes: Math.round(p.n * (0.5 + rnd() * 0.8)),
    };
  }
  // a past stream of this channel: its cover, the numbers, and what the viewers said (the pools of the replay page)
  fromStream(l) {
    const key = 's' + l.t;
    if (this.cache[key]) return this.cache[key];
    const rnd = fmRng(fmHash(key + (l.title || '')));
    const pick = (a) => a[Math.floor(rnd() * a.length)];
    const car = CARS.find((c) => c.name === l.car) || carById(this.lot.pf.data.cur);
    const base = { cn: car.cn || car.name.split(' ')[0], short: car.name.split(' ')[0], car: car.name, eng: car.layout, engTxt: car.engTxt };
    const lines = [['start', 0], ['eng_' + car.eng, 0]];
    if (l.top >= 250) lines.push(['fast250', l.top]); else if (l.top >= 200) lines.push(['fast200', l.top]);
    if (l.lv > 0) lines.push(['lv' + Math.min(5, l.lv), Math.min(5, l.lv)]);
    lines.push([l.kind, 0], [l.kind + '2', 0], ['late', 0]);
    const used = new Set(), age = Math.max(3, (Date.now() - l.t) / 60000), re = [];
    lines.forEach(([k, n], i) => {
      const pool = CM[k]; if (!pool) return;
      const name = cmNick(used);
      re.push({ name, text: cmJitter(cmFill(pick(pool), Object.assign({ n }, base))), likes: Math.round(Math.pow(rnd(), 3) * 40), q: 0, ago: Math.max(1, age * (k === 'late' ? 0.12 : 0.9 - i * 0.09) * (0.8 + rnd() * 0.2)) });
      if (rnd() < 0.5) {
        const rp = CM_RP[l.kind] && rnd() < 0.5 ? CM_RP[l.kind] : CM_RP.gen;
        const par = re[re.length - 1];
        re.push({ name: cmNick(used), text: cmJitter(pick(rp)), likes: Math.round(Math.pow(rnd(), 4) * 12), q: 0, par, ago: Math.max(1, par.ago * (0.5 + rnd() * 0.4)) });
      }
    });
    re.sort((a, b) => b.ago - a.ago);
    re.forEach((r) => { if (r.par) r.q = re.indexOf(r.par) + 2; });
    const kd = { arrest: '被截停', wreck: '撞毁', quit: '平安收工' }[l.kind] || '';
    const facts = [['最高时速', (l.top || 0) + ' km/h'], ['通缉等级', l.lv ? '★' + l.lv : '无'], ['结局', kd], [l.net >= 0 ? '净收益' : '净亏损', (l.net >= 0 ? '+' : '') + fmtMoney(l.net)]];
    const ch = this.lot.pf.data.name || '夜行记录仪';
    const post = {
      kind: 'stream', key, title: l.title || '未命名直播', board: '直播回放', au: ch, vip: false, lv: 5, age, n: re.length, cover: l.thumb || '', facts,
      body: [(l.car || '') + ' · ' + agoTxt(l.t) + '开的播。'], re, views: Math.round(60 + rnd() * 900), likes: Math.round(rnd() * 120),
    };
    this.cache[key] = post;
    return post;
  }
  openThread(p) { this.seen.add(p.t); this.show(this.fromThread(p)); }
  openStream(l) { this.show(this.fromStream(l)); }
  // ---- the sheet
  show(p) {
    const root = this.$('thr'), sc = this.$('thrScroll');
    clearTimeout(this.tm);
    root.classList.remove('out');
    this.$('thrBoard').textContent = p.board;
    this.$('thrKind').textContent = p.kind === 'stream' ? 'REPLAY' : p.n >= 150 ? 'HOT THREAD' : 'THREAD';
    root.dataset.kind = p.kind;
    sc.innerHTML = '';
    let i = 0;
    const put = (el) => { el.style.setProperty('--i', String(i++)); sc.appendChild(el); return el; };
    put(domEl('h2', 'thrT', p.title));
    const op = put(domEl('div', 'thrOP'));
    op.appendChild(upAv(p.au));
    const who = domEl('div', 'thrWho');
    const nm = domEl('div', 'cmN');
    nm.appendChild(domEl('b', p.vip ? 'vip' : '', p.au));
    nm.appendChild(domEl('span', 'lv l' + p.lv, 'LV' + p.lv));
    nm.appendChild(domEl('em', 'thrTag', p.kind === 'stream' ? '主播' : '楼主'));
    who.appendChild(nm);
    who.appendChild(domEl('div', 'thrMeta', fmAgo(p.age) + (p.kind === 'stream' ? '' : ' · 阅读 ' + fmtNum(p.views)) + ' · 回帖 ' + fmtNum(p.n)));
    op.appendChild(who);
    if (p.kind === 'stream') {
      const cv = put(domEl('div', 'thrCover'));
      if (p.cover) { const im = new Image(); im.src = p.cover; im.alt = ''; cv.appendChild(im); } else cv.appendChild(domEl('span', '', 'NO IMAGE'));
      const fx = put(domEl('div', 'thrFacts'));
      for (const f of p.facts) { const d = domEl('div', ''); d.appendChild(domEl('small', '', f[0])); d.appendChild(domEl('b', '', f[1])); fx.appendChild(d); }
    } else {
      const bd = put(domEl('div', 'thrBody'));
      for (const t of p.body) bd.appendChild(domEl('p', '', cmEmoji(t)));
    }
    const lk = put(domEl('div', 'thrLk'));
    const like = domEl('span', 'lk'); like.appendChild(upIc('like')); const lc = domEl('b', '', fmtW(p.likes)); like.appendChild(lc);
    let on = false; like.onclick = () => { on = !on; like.classList.toggle('on', on); lc.textContent = fmtW(p.likes + (on ? 1 : 0)); };
    lk.appendChild(like);
    const cm = domEl('span', 'lk static'); cm.appendChild(upIc('cmt')); cm.appendChild(domEl('b', '', fmtW(p.n))); lk.appendChild(cm);
    const rh = put(domEl('div', 'thrRH'));
    rh.appendChild(document.createTextNode('全部回帖'));
    rh.appendChild(domEl('em', '', 'REPLIES · ' + fmtNum(p.n)));
    p.re.forEach((r, k) => put(this.reply(p, r, k + 2)));
    put(domEl('div', 'thrEnd', p.n > p.re.length ? '已显示 ' + p.re.length + ' 条热门回帖 · 共 ' + fmtNum(p.n) + ' 条' : '没有更多回帖了'));
    root.classList.add('on'); root.setAttribute('aria-hidden', 'false');
    sc.scrollTop = 0;   // only works once the sheet has a box again
    this.isOpen = true;
    const x = this.$('thrX'); try { x.focus({ preventScroll: true }); } catch (e) { }
  }
  reply(p, r, floor) {
    const el = domEl('div', 'thrR' + (r.name === p.au ? ' op' : ''));
    el.appendChild(upAv(r.name, 's'));
    const b = domEl('div', 'thrRB');
    const nm = domEl('div', 'cmN');
    nm.appendChild(domEl('b', fmVip(r.name) ? 'vip' : '', r.name));
    nm.appendChild(domEl('span', 'lv l' + fmLv(r.name), 'LV' + fmLv(r.name)));
    if (r.name === p.au) nm.appendChild(domEl('em', 'thrTag', p.kind === 'stream' ? '主播' : '楼主'));
    b.appendChild(nm);
    if (r.q >= 1 && r.q < floor) {
      const src = r.q === 1 ? { name: p.au, text: p.body[0] } : p.re[r.q - 2];
      if (src) {
        const q = domEl('div', 'thrQ');
        q.appendChild(domEl('b', '', '#' + r.q + ' ' + src.name + '：'));
        const tx = String(src.text).replace(/\[[^\]\s]{1,4}\]/g, '');
        q.appendChild(document.createTextNode(tx.length > 34 ? tx.slice(0, 34) + '…' : tx));
        b.appendChild(q);
      }
    }
    b.appendChild(domEl('div', 'thrRT', cmEmoji(r.text)));
    const f = domEl('div', 'thrRF');
    f.appendChild(domEl('span', 'fl', '#' + floor));
    f.appendChild(domEl('span', '', fmAgo(r.ago)));
    const lk = domEl('span', 'lk'); lk.appendChild(upIc('like')); const lc = domEl('b', '', r.likes > 0 ? fmtW(r.likes) : '赞'); lk.appendChild(lc);
    let on = false; lk.onclick = () => { on = !on; lk.classList.toggle('on', on); lc.textContent = fmtW(r.likes + (on ? 1 : 0)) || '赞'; };
    f.appendChild(lk);
    b.appendChild(f);
    el.appendChild(b);
    return el;
  }
  close(now) {
    const root = this.$('thr');
    if (!this.isOpen) return;
    this.isOpen = false; root.setAttribute('aria-hidden', 'true');
    clearTimeout(this.tm);
    if (now) { root.classList.remove('on', 'out'); return; }
    root.classList.add('out');
    this.tm = setTimeout(() => root.classList.remove('on', 'out'), 230);
  }
  // keys while the sheet is open: Esc / Backspace close it, the arrows scroll it
  key(e) {
    const c = e.code, sc = this.$('thrScroll');
    if (c === 'Escape' || c === 'Backspace' || c === 'Enter' || c === 'NumpadEnter') { this.close(); return true; }
    const step = { ArrowDown: 1, ArrowUp: -1, PageDown: 8, PageUp: -8, Space: 8, Home: -999, End: 999 }[c];
    if (step) { sc.scrollBy({ top: step * 3.2 * parseFloat(getComputedStyle(sc).fontSize), behavior: 'smooth' }); return true; }
    return c === 'KeyQ' || c === 'KeyE' || c === 'ArrowLeft' || c === 'ArrowRight';
  }
}

