// v69: small UI motion helpers (class toggles only - the visuals live in the CSS)
(function () {
  try {
    const kick = (el, cls) => { el.classList.remove(cls); void el.offsetWidth; el.classList.add(cls); };
    for (const id of ['liveName', 'gName']) {
      const el = document.getElementById(id); if (!el) continue;
      let last = el.textContent;
      new MutationObserver(() => { const t = el.textContent; if (t !== last) { last = t; kick(el, 'fxPop'); } }).observe(el, { childList: true, characterData: true, subtree: true });
    }
    document.addEventListener('pointerdown', (e) => {
      const b = e.target && e.target.closest ? e.target.closest('button') : null;
      if (!b || b.disabled) return;
      kick(b, 'fxPress');
      b.addEventListener('animationend', () => b.classList.remove('fxPress'), { once: true });
    }, true);
  } catch (e) { }
})();

