    this.clock0 = (() => { const d = new Date(); d.setHours(22 + Math.floor(Math.random() * 3), Math.floor(Math.random() * 60), Math.floor(Math.random() * 60)); return d.getTime(); })();
    this.osdT = 0; this.osdKmh = 0;
    this.gp = { prev: [], active: false };
