    this.applySettings();
    window.addEventListener('resize', () => this.resize());
    this.resize();
    document.addEventListener('visibilitychange', () => { if (document.hidden && this.mode === 'play') this.pause(); });
    window.addEventListener('blur', () => { if (this.mode === 'play' && !QS.has('test')) this.pause(); });
    this.showroom = new Showroom(); this.lot = new Lot(this); this.mob = MOBILE ? new Mobile(this) : null; this.perf = MOBILE ? new Perf(this) : null;
    if (QS.has('test')) { this.mode = 'play'; this.set.stutter = 0; this.testMode = true; } else this.lot.show();
    // test hook: advance simulation + render synchronously
