    const snowy = this.world.snow >= 0.5;
    // contact patch of a wheel in road space for a car at (s,d) with heading psi: f forwards, l to the side (+d)
    const wpos = (s, d, psi, f, l, h) => road.pos(s + f * Math.cos(psi) - l * Math.sin(psi), d + f * Math.sin(psi) + l * Math.cos(psi), h);
