// ---- 14c_perf.js ----
// Mobile build: performance panel (replaces the driving-info HUD). CPU time per frame (simulation / render
// submission), GPU time via EXT_disjoint_timer_query_webgl2 when the browser exposes it, draw calls, render size.
class Perf {
  constructor(g) {
    this.g = g; this.el = document.createElement('div'); this.el.id = 'perf'; document.body.appendChild(this.el);
    this.ext = null; try { this.ext = gl.getExtension('EXT_disjoint_timer_query_webgl2'); } catch (e) { }
    this.qs = []; this.qa = null; this.gpu = []; this.est = []; this.qN = 0;
    this.ft = []; this.sim = []; this.sub = []; this.renders = 0; this.dc = 0; this.dcF = []; this.t = 0; this.last = 0;
    this.gpuName = '';
    try { const d = gl.getExtension('WEBGL_debug_renderer_info'); if (d) this.gpuName = String(gl.getParameter(d.UNMASKED_RENDERER_WEBGL) || ''); } catch (e) { }
    // count draw calls
    const self = this;
    for (const f of ['drawArrays', 'drawElements', 'drawArraysInstanced', 'drawElementsInstanced']) {
      const o = gl[f]; if (typeof o !== 'function') continue;
      gl[f] = function () { self.dc++; return o.apply(this, arguments); };
    }
  }
  on() { return this.g.set.perf && this.g.mode === 'play'; }
  gpuBegin() {
    if (!this.on()) return;
    if (!this.ext || this.noQ) {   // no timer queries (e.g. Chrome on Adreno): every 15th frame, drain the GPU and time one frame with gl.finish()
      if ((this.fN = (this.fN || 0) + 1) % 15) return;
      gl.finish(); this.fT0 = performance.now(); this.syncF = true; return;
    }
    if (this.qa) return;
    const q = this.qs.pop() || gl.createQuery();
    gl.beginQuery(this.ext.TIME_ELAPSED_EXT, q); this.qa = q;
  }
  gpuEnd() {
    if (this.fT0) { gl.finish(); this.est.push(performance.now() - this.fT0); this.fT0 = 0; return; }
    if (!this.qa) return;
    gl.endQuery(this.ext.TIME_ELAPSED_EXT); (this.pend || (this.pend = [])).push(this.qa); this.qa = null;
  }
  gpuPoll() {
    const P = this.pend; if (!P || !P.length) return;
    const dis = gl.getParameter(this.ext.GPU_DISJOINT_EXT);
    while (P.length && gl.getQueryParameter(P[0], gl.QUERY_RESULT_AVAILABLE)) {
      const q = P.shift(), ns = gl.getQueryParameter(q, gl.QUERY_RESULT);
      if (!dis && ns > 0) this.gpu.push(ns / 1e6); else this.qN++;
      this.qs.push(q);
    }
    if (P.length > 8) { for (const q of P) this.qs.push(q); P.length = 0; this.qN += 8; }
    if (this.qN > 30 && !this.gpu.length) this.noQ = true;   // queries exist but never return usable results
  }
  // called once per rAF from Game.loop: frame interval, simulation ms, render-submission ms, rendered?
  frame(now, simMs, subMs, rendered) {
    const show = this.on();
    this.el.style.display = show ? '' : 'none';
    if (!show) { this.last = now; this.dc = 0; return; }
    if (this.last) this.ft.push(now - this.last);
    this.last = now;
    if (rendered) { this.renders++; if (!this.syncF) { this.sim.push(simMs); this.sub.push(subMs); } this.dcF.push(this.dc); }
    this.syncF = false;
    this.dc = 0;
    if (this.ext) this.gpuPoll();
    this.t += this.ft.length ? this.ft[this.ft.length - 1] : 0;
    if (this.t < 500) return;
    const avg = (a) => a.length ? a.reduce((x, y) => x + y, 0) / a.length : 0;
    const span = this.ft.reduce((x, y) => x + y, 0) || 1, fps = this.renders * 1000 / span;
    const fts = this.ft.slice().sort((a, b) => b - a), worst = fts[0] || 0;
    const sim = avg(this.sim), sub = avg(this.sub), cpu = sim + sub;
    const est = this.est.length ? Math.max(avg(this.est) - sub, avg(this.est) * 0.5) : null, gpu = this.gpu.length ? avg(this.gpu) : est;
    const frameMs = this.renders ? span / this.renders : 0;
    let neck;
    if (gpu != null) neck = gpu > cpu * 1.15 ? 'GPU' : cpu > gpu * 1.15 ? 'CPU' : 'CPU ≈ GPU';
    else neck = cpu > frameMs * 0.75 ? 'CPU' : 'GPU（推测）';
    const R = this.g.renderer, c = this.g.canvas, f1 = (x) => x.toFixed(1);
    const gtx = this.gpu.length ? f1(gpu) + ' ms' : est != null ? '≈' + f1(est) + ' ms（估算）' : this.ext && !this.noQ ? '测量中' : '估算中';
    const col = fps >= 55 ? '#6fe08a' : fps >= 28 ? '#ffd166' : '#ff6b6b';
    this.el.innerHTML = `<b style="color:${col}">${Math.round(fps)}</b><small> FPS</small> · 帧 ${f1(frameMs)} ms · 最慢 ${f1(worst)} ms<br>`
      + `CPU ${f1(cpu)} ms（模拟 ${f1(sim)} · 渲染提交 ${f1(sub)}）<br>`
      + `GPU ${gtx} · 瓶颈 ${neck}<br>`
      + `${c.width}×${c.height} · 画质 ${({ high: '高', mid: '中', low: '低' })[R.qName] || R.qName || '-'} · 绘制 ${Math.round(avg(this.dcF))} 次/帧`
      + (this.gpuName ? `<br><span>${this.gpuName.replace(/[<>&]/g, '')}</span>` : '');
    this.ft = []; this.sim = []; this.sub = []; this.gpu = []; this.dcF = []; if (this.est.length > 6) this.est = this.est.slice(-3); this.renders = 0; this.t = 0;
  }
}



// ---- 15_toy_rank.js ----
// ============================================================================
// Toy 平台集成：设置页版本号是「累计里程榜」的隐藏入口。
// 用事件委托绑定，脚本与 DOM 的先后顺序不影响。
(function () {
  'use strict';
  document.addEventListener('click', function (e) {
    var n = e.target;
    while (n && n !== document) {
      if (n.id === 'verTag') {
        e.preventDefault();
        if (window.ToyRank) window.ToyRank.open();
        return;
      }
      n = n.parentNode;
    }
  });
})();
